using System.Collections;
using UnityEngine;

#if ENABLE_INPUT_SYSTEM
using UnityEngine.InputSystem;
#endif

[DefaultExecutionOrder(-50)]
public class BeerGlassPour : MonoBehaviour
{
    public Camera playerCamera;

    public GameObject schoonerGlass;
    public GameObject pintGlass;

    public GameObject schoonerPourVisual;
    public GameObject pintPourVisual;

    public Transform beerNozzle;

    public float pickupDistance = 2.5f;
    public float nozzleDistance = 3f;
    public float nozzleAimAngle = 90f;
    public float pourDuration = 2.5f;
    public float beerStreamLength = 0.65f;

    public Vector3 holdLocalPosition = new Vector3(0.32f, -0.28f, 1.25f);
    public Vector3 heldGlassLocalRotation = new Vector3(0f, 0f, 0f);

    private UniformInteraction uniform;
    private ActionSounds sounds;
    private WaypointBeacon stationBeacon;
    private BoxCollider guideFloor;
    private int cocktailGuideSide;
    private BeerGuidance beerGuidance;
    private Coroutine beerGuideRoutine;
    private bool beerIntroStarted, guideBusy, cocktailBriefingCompleted;
    private bool waitForBeerServeSound;
    private int pendingBeerInstruction = -1;
    private int guideInputFrame = -1;
    public bool IsGuidePlaying => guideBusy || guideInputFrame == Time.frameCount;
    private int ExpectedBeerGlass => barOpened && night != null ? night.ExpectedBeerIndex : served[0] ? 1 : 0;
    private Transform holdPoint;
    private GameObject heldGlass;

    private Transform originalParent;
    private Vector3 originalLocalPosition;
    private Quaternion originalLocalRotation;
    private Vector3 originalLocalScale;
    private Collider[] heldColliders;

    private GameObject beerStream;
    private bool pouring;
    private readonly bool[] filled = new bool[2];
    private readonly bool[] served = new bool[2];
    private GameObject serviceMarker;
    private BoxCollider serviceDesk;
    private CocktailEquipment cocktailEquipment;
    private RecipeCards recipeCards;
    private CocktailPractice practice;
    private int practiceReturnFrame = -1;
    private readonly int[] passedTrials = new int[3];
    private bool barOpened;
    private NightService night;
    private readonly GlassHome[] glassHomes = new GlassHome[2];
    private bool AllTrialsComplete => passedTrials[0] >= 3 && passedTrials[1] >= 3 && passedTrials[2] >= 3;
    public bool IsRecipeOpen => barOpened ? night != null && night.IsDialogOpen
        : practiceReturnFrame == Time.frameCount || (recipeCards != null && recipeCards.BlocksInput);
    private readonly LineRenderer[] serviceRings = new LineRenderer[2];
    private Material markerMaterial;
    private Material completedMaterial;
    private Material liquidMaterial;
    private Material foamMaterial;
    private Material streamMaterial;
    private readonly GameObject[] filledVisuals = new GameObject[2];
    public bool TaskCompleted => served[0] && served[1];

    private string prompt = "";
    private GUIStyle textStyle;
    private string actionTitle = "";
    private string actionDetail = "";
    private float actionUntil;
    private GUIStyle actionTitleStyle;
    private GUIStyle actionDetailStyle;

    void Start()
    {
        uniform = GetComponent<UniformInteraction>();
        if (playerCamera == null)
            playerCamera = GetComponentInChildren<Camera>();

        if (playerCamera == null)
        {
            Debug.LogError("BeerGlassPour: Player Camera를 연결하세요.");
            enabled = false;
            return;
        }

        sounds = new ActionSounds(this);
        beerGuidance = new BeerGuidance(this);

        GameObject holdObject = new GameObject("BeerGlass_HoldPoint");
        holdObject.transform.SetParent(playerCamera.transform, false);
        holdObject.transform.localPosition = holdLocalPosition;
        holdObject.transform.localRotation = Quaternion.identity;
        holdPoint = holdObject.transform;

        PreparePourVisual(schoonerPourVisual);
        PreparePourVisual(pintPourVisual);

        glassHomes[0] = new GlassHome(schoonerGlass);
        glassHomes[1] = new GlassHome(pintGlass);
        CreateBeerStream();
        CreateServiceMarker();
        cocktailEquipment = new CocktailEquipment(this);
        recipeCards = new RecipeCards(this, cocktailEquipment.Table);
        stationBeacon = new WaypointBeacon(gameObject, true, true);
        foreach (GameObject sceneRoot in gameObject.scene.GetRootGameObjects())
            foreach (BoxCollider floor in sceneRoot.GetComponentsInChildren<BoxCollider>())
                if (floor.name == "BeerStage_Floor" && !floor.isTrigger) guideFloor = floor;
    }

    void Update()
    {
        if (practice != null && practice.IsActive)
        {
            practice.Tick();
            return;
        }
        prompt = "";
        if (barOpened && night != null) { night.Tick(); return; }

        if (IsRecipeOpen)
        {
            if (recipeCards.IsOpen && PressedRecipeClose()) recipeCards.Close();
            return;
        }

        if (uniform == null || !uniform.isActiveAndEnabled
            || !uniform.ShiftCompleted || uniform.IsGuidePlaying)
            return;

        if (pendingBeerInstruction >= 0)
        {
            if (beerGuideRoutine == null) beerGuideRoutine = StartCoroutine(PlayQueuedBeerGuide());
            return;
        }
        if (IsGuidePlaying) return;
        if (!beerIntroStarted)
        {
            if (IsNearBeerStation())
            {
                beerIntroStarted = true;
                QueueBeerGuide(0);
            }
            else prompt = "Walk to the beer tap to hear your first instruction.";
            return;
        }
        if (TaskCompleted && !cocktailBriefingCompleted)
        {
            if (IsNearCocktailStation()) QueueBeerGuide(3, true);
            else prompt = "Walk around the bar to the rear cocktail table.";
            return;
        }
        if (recipeCards != null) recipeCards.SetAvailable(cocktailBriefingCompleted);

        if (serviceMarker != null)
        {
            serviceMarker.SetActive(true);
            float width = TaskCompleted ? 0.035f : 0.025f + Mathf.Sin(Time.time * 3f) * 0.005f;
            foreach (LineRenderer ring in serviceRings)
                if (ring != null) ring.widthMultiplier = width;
        }

        if (Cursor.lockState != CursorLockMode.Locked)
            return;

        if (recipeCards != null && recipeCards.HandleInput(PressedLeftClick(), out string recipePrompt))
        {
            prompt = recipePrompt;
            return;
        }

        if (cocktailBriefingCompleted && heldGlass == null && cocktailEquipment != null
            && cocktailEquipment.HandleInput(PressedLeftClick(), out string equipmentPrompt))
        {
            prompt = equipmentPrompt;
            return;
        }

        if (TaskCompleted)
            return;

        if (pouring)
        {
            prompt = "Pouring beer...";
            return;
        }

        if (heldGlass == null)
        {
            CheckGlassPickup();
        }
        else
        {
            if (IsAimingAtServiceMarker())
            {
                int index = HeldGlassIndex();
                prompt = filled[index]
                    ? "Left Click - Serve beer on the glowing marker"
                    : "Fill this glass at the beer tap before serving.";
                if (PressedLeftClick() && filled[index])
                    ServeGlass(index);
                return;
            }

            CheckPouring();

            if (PressedLeftClick() && !pouring)
                DropGlass();
        }
    }

    void LateUpdate()
    {
        if (stationBeacon == null) return;
        if (uniform == null || !uniform.ShiftStarted
            || (barOpened && (night == null || (!night.HasBeerOrder && !night.HasCocktailOrder)))
            || (practice != null && practice.IsActive) || IsRecipeOpen)
        {
            stationBeacon.Hide();
            return;
        }
        CharacterController controller = GetComponent<CharacterController>();
        float radius = controller != null ? controller.radius * Mathf.Max(Mathf.Abs(transform.lossyScale.x), Mathf.Abs(transform.lossyScale.z)) : 0.3f;
        float floorY = guideFloor != null ? guideFloor.transform.TransformPoint(guideFloor.center + Vector3.up * guideFloor.size.y * 0.5f).y : 0.05f;
        if (night != null && night.HasBeerOrder && heldGlass != null && filled[HeldGlassIndex()] && serviceMarker != null)
        {
            Vector3 approach = serviceMarker.transform.position;
            if (serviceDesk != null) approach.z = transform.position.z <= serviceDesk.bounds.center.z
                ? serviceDesk.bounds.min.z - radius - 0.15f : serviceDesk.bounds.max.z + radius + 0.15f;
            stationBeacon.Show(serviceMarker.transform.position + Vector3.up * 0.65f, playerCamera, "SERVE ORDER");
            stationBeacon.SetTrail(transform.position, approach, floorY);
            return;
        }
        if ((!beerIntroStarted || (night != null && night.HasBeerOrder)) && beerNozzle != null)
        {
            Vector3 approach = beerNozzle.position;
            if (serviceDesk != null)
            {
                Bounds bar = serviceDesk.bounds;
                approach.z = transform.position.z <= bar.center.z ? bar.min.z - radius - 0.15f : bar.max.z + radius + 0.15f;
                if (transform.position.z > bar.min.z - radius && transform.position.z < bar.max.z + radius)
                    approach = transform.position; // 카운터 옆 통로에서는 직선으로 가로지르는 경로를 그리지 않습니다.
            }
            stationBeacon.Show(beerNozzle.position + Vector3.up * 0.42f, playerCamera, "BEER STATION");
            stationBeacon.SetTrail(transform.position, approach, floorY);
            return;
        }
        if ((!TaskCompleted && !(night != null && night.HasCocktailOrder)) || recipeCards == null || !recipeCards.TryGetFocusPoint(out Vector3 focus))
        {
            stationBeacon.Hide();
            return;
        }
        Vector3 destination = focus;
        BoxCollider table = cocktailEquipment != null ? cocktailEquipment.Table : null;
        if (table != null) destination.z = table.bounds.min.z - radius - 0.05f;
        Vector3 marker = focus + Vector3.up * 0.38f;
        string caption = "COCKTAIL NOTES";
        if (serviceDesk != null && guideFloor != null)
        {
            Bounds bar = serviceDesk.bounds;
            Bounds floor = guideFloor.bounds;
            float margin = radius + (controller != null ? controller.skinWidth : 0.08f) + 0.05f;
            float left = Mathf.Max(bar.min.x - radius - 0.05f, floor.min.x + margin);
            float right = Mathf.Min(bar.max.x + radius + 0.05f, floor.max.x - margin);
            float front = bar.min.z - radius - 0.25f;
            float back = bar.max.z + radius + 0.25f;
            if (transform.position.x <= bar.min.x) cocktailGuideSide = -1;
            else if (transform.position.x >= bar.max.x) cocktailGuideSide = 1;
            if (cocktailGuideSide == 0)
            {
                float leftCost = FlatDistance(transform.position, new Vector3(left, 0f, front)) + FlatDistance(new Vector3(left, 0f, back), destination);
                float rightCost = FlatDistance(transform.position, new Vector3(right, 0f, front)) + FlatDistance(new Vector3(right, 0f, back), destination);
                cocktailGuideSide = rightCost < leftCost ? 1 : -1;
            }
            float side = cocktailGuideSide > 0 ? right : left;
            bool atSide = cocktailGuideSide > 0 ? transform.position.x >= bar.max.x + radius + 0.005f
                : transform.position.x <= bar.min.x - radius - 0.005f;
            if (transform.position.z < bar.max.z + radius + 0.04f)
            {
                bool inSidePassage = (transform.position.x <= bar.min.x || transform.position.x >= bar.max.x)
                    && transform.position.z >= bar.min.z;
                destination = transform.position.z >= bar.max.z
                    ? new Vector3(transform.position.x, floorY, back)
                    : new Vector3(side, floorY, atSide || inSidePassage ? back : front);
                marker = destination + Vector3.up * 1.2f;
                caption = "AROUND THE BAR";
            }
            else if (table != null && transform.position.z > destination.z + 0.05f
                && (transform.position.x <= table.bounds.min.x || transform.position.x >= table.bounds.max.x))
            {
                destination.x = transform.position.x; // 테이블 옆에서 접근할 때도 먼저 앞쪽 통로로 안내합니다.
            }
        }
        stationBeacon.Show(marker, playerCamera, caption);
        stationBeacon.SetTrail(transform.position, destination, floorY);
    }

    static float FlatDistance(Vector3 first, Vector3 second)
    {
        first.y = second.y = 0f;
        return Vector3.Distance(first, second);
    }

    void QueueBeerGuide(int instruction, bool waitForServeSound = false)
    {
        if (guideBusy || pendingBeerInstruction >= 0) return;
        pendingBeerInstruction = instruction;
        waitForBeerServeSound = waitForServeSound;
        beerGuideRoutine = StartCoroutine(PlayQueuedBeerGuide());
    }

    IEnumerator PlayQueuedBeerGuide()
    {
        int instruction = pendingBeerInstruction;
        guideBusy = true;
        guideInputFrame = Time.frameCount;
        prompt = "";
        if (recipeCards != null) recipeCards.SetAvailable(false);
        try
        {
            if (waitForBeerServeSound && sounds != null) yield return sounds.WaitForResult();
            else yield return null;
            if (beerGuidance != null) yield return beerGuidance.Play(instruction);
            if (instruction == 3) cocktailBriefingCompleted = true;
            pendingBeerInstruction = -1;
        }
        finally
        {
            guideBusy = false;
            guideInputFrame = Time.frameCount;
            beerGuideRoutine = null;
        }
    }

    void CancelBeerGuide()
    {
        if (beerGuideRoutine != null) StopCoroutine(beerGuideRoutine);
        beerGuideRoutine = null;
        if (beerGuidance != null) beerGuidance.Stop();
        guideBusy = false;
        guideInputFrame = Time.frameCount;
        // 중단된 안내는 pending을 유지해 컴포넌트를 다시 켜면 재생합니다.
    }

    bool IsNearBeerStation()
    {
        if (beerNozzle == null) return false;
        Vector3 offset = beerNozzle.position - transform.position;
        offset.y = 0f;
        return offset.sqrMagnitude <= 2.25f * 2.25f;
    }

    bool IsNearCocktailStation()
    {
        if (recipeCards == null || !recipeCards.TryGetFocusPoint(out Vector3 focus)) return false;
        Vector3 offset = focus - transform.position;
        offset.y = 0f;
        return offset.sqrMagnitude <= 1.6f * 1.6f;
    }

    void CheckGlassPickup()
    {
        Ray ray = playerCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));

        if (!Physics.Raycast(ray, out RaycastHit hit, pickupDistance,
            Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore))
            return;

        Transform target = hit.collider.transform;

        if ((barOpened || !served[0]) && schoonerGlass != null && target.IsChildOf(schoonerGlass.transform))
        {
            prompt = "Left Click - Pick up schooner";

            if (PressedLeftClick())
                PickUpGlass(schoonerGlass);

            return;
        }

        if ((barOpened || !served[1]) && pintGlass != null && target.IsChildOf(pintGlass.transform))
        {
            prompt = "Left Click - Pick up pint";

            if (PressedLeftClick())
                PickUpGlass(pintGlass);

            return;
        }
    }

    void PickUpGlass(GameObject glass)
    {
        if (IsGuidePlaying || (!barOpened && TaskCompleted)) return;
        int index = glass == schoonerGlass ? 0 : 1;
        if (index != ExpectedBeerGlass)
        {
            ShowAction("WRONG GLASS", "Choose the " + (ExpectedBeerGlass == 0 ? "schooner" : "pint") + " glass.");
            if (!barOpened) QueueBeerGuide(1);
            return;
        }
        heldGlass = glass;

        originalParent = glass.transform.parent;
        originalLocalPosition = glass.transform.localPosition;
        originalLocalRotation = glass.transform.localRotation;
        originalLocalScale = glass.transform.localScale;

        heldColliders = glass.GetComponentsInChildren<Collider>(true);

        foreach (Collider collider in heldColliders)
            collider.enabled = false;

        glass.transform.SetParent(holdPoint, false);
        glass.transform.localPosition = Vector3.zero;
        glass.transform.localRotation = Quaternion.Euler(heldGlassLocalRotation);
        glass.transform.localScale = originalLocalScale;

        SetVisible(glass, true);
        ShowAction("GLASS PICKED UP", glass == schoonerGlass ? "Schooner selected." : "Pint selected.");
    }

    void DropGlass()
    {
        if (heldGlass == null)
            return;

        SetVisible(heldGlass, true);

        heldGlass.transform.SetParent(originalParent, false);
        heldGlass.transform.localPosition = originalLocalPosition;
        heldGlass.transform.localRotation = originalLocalRotation;
        heldGlass.transform.localScale = originalLocalScale;

        if (heldColliders != null)
        {
            foreach (Collider collider in heldColliders)
                collider.enabled = true;
        }

        heldGlass = null;
        heldColliders = null;
        ShowAction("GLASS RETURNED", "The glass is back in its original place.", 1.8f);
    }

    void CheckPouring()
    {
        if (filled[HeldGlassIndex()])
        {
            prompt = "Beer ready! Find the glowing SERVE marker. Left Click elsewhere to return glass.";
            return;
        }

        if (beerNozzle == null)
        {
            prompt = "Beer nozzle is not connected.";
            return;
        }

        if (CanPour())
        {
            prompt = "E - Pour beer";

            if (PressedInteract() && !pouring)
                StartCoroutine(PourBeer());
        }
        else
        {
            prompt = "Move closer to the beer nozzle";
        }
    }

    bool CanPour()
    {
        Vector3 toNozzle = beerNozzle.position - playerCamera.transform.position;

        if (toNozzle.magnitude > nozzleDistance)
            return false;

        float angle = Vector3.Angle(playerCamera.transform.forward, toNozzle.normalized);

        return angle <= nozzleAimAngle;
    }

    IEnumerator PourBeer()
    {
        pouring = true;
        prompt = "";

        GameObject pourVisual = GetPourVisualForHeldGlass();

        if (pourVisual == null)
        {
            Debug.LogWarning("Pour visual glass가 연결되지 않았습니다.");
            pouring = false;
            yield break;
        }

        SetVisible(heldGlass, false);
        SetVisible(pourVisual, true);

        if (beerStream != null)
            beerStream.SetActive(true);

        float timer = 0f;

        try
        {
            while (timer < pourDuration)
            {
                if (sounds != null) sounds.PlayContinuous(ActionSound.BeerPour);
                timer += Time.deltaTime;
                PositionBeerStream();
                yield return null;
            }
        }
        finally
        {
            if (sounds != null) sounds.StopContinuous();
        }

        if (beerStream != null)
            beerStream.SetActive(false);

        SetVisible(pourVisual, false);
        SetVisible(heldGlass, true);

        int index = HeldGlassIndex();
        filled[index] = true;
        CreateFilledVisual(index);
        pouring = false;
        ShowAction("BEER READY", "Filling complete. Place the glass on the glowing SERVE marker.", 3f);
    }

    GameObject GetPourVisualForHeldGlass()
    {
        if (heldGlass == schoonerGlass)
            return schoonerPourVisual;

        if (heldGlass == pintGlass)
            return pintPourVisual;

        return null;
    }

    void PreparePourVisual(GameObject visual)
    {
        if (visual == null)
            return;

        visual.SetActive(true);
        SetVisible(visual, false);

        Collider[] colliders = visual.GetComponentsInChildren<Collider>(true);
        foreach (Collider collider in colliders)
            collider.enabled = false;
    }

    void SetVisible(GameObject target, bool visible)
    {
        if (target == null)
            return;

        target.SetActive(true);

        Renderer[] renderers = target.GetComponentsInChildren<Renderer>(true);

        foreach (Renderer renderer in renderers)
            renderer.enabled = visible;
    }

    void CreateBeerStream()
    {
        beerStream = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
        beerStream.name = "BeerStream_Runtime";

        Collider streamCollider = beerStream.GetComponent<Collider>();
        if (streamCollider != null)
            Destroy(streamCollider);

        Renderer renderer = beerStream.GetComponent<Renderer>();

        Shader shader = Shader.Find("Universal Render Pipeline/Lit");
        if (shader == null)
            shader = Shader.Find("Standard");

        streamMaterial = new Material(shader);
        streamMaterial.color = new Color(1f, 0.65f, 0.05f, 0.85f);

        renderer.sharedMaterial = streamMaterial;

        beerStream.SetActive(false);
    }

    void PositionBeerStream()
    {
        if (beerStream == null || beerNozzle == null)
            return;

        beerStream.transform.position =
            beerNozzle.position + Vector3.down * (beerStreamLength * 0.5f);

        beerStream.transform.rotation = Quaternion.identity;
        beerStream.transform.localScale =
            new Vector3(0.035f, beerStreamLength * 0.5f, 0.035f);
    }

    int HeldGlassIndex()
    {
        return heldGlass == schoonerGlass ? 0 : 1;
    }

    bool IsAimingAtServiceMarker()
    {
        if (serviceMarker == null)
            return false;

        Ray ray = playerCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
        if (!Physics.Raycast(ray, out RaycastHit hit, pickupDistance,
            Physics.DefaultRaycastLayers, QueryTriggerInteraction.Collide))
            return false;

        if (hit.transform.IsChildOf(serviceMarker.transform))
            return true;

        // 링뿐 아니라 링이 놓인 상판을 눌러도 서빙합니다.
        Vector3 offset = hit.point - serviceMarker.transform.position;
        return hit.collider == serviceDesk && Mathf.Abs(offset.x) <= 0.85f
            && Mathf.Abs(offset.z) <= 0.6f && Mathf.Abs(offset.y) <= 0.2f;
    }

    void ServeGlass(int index)
    {
        if (!filled[index] || (!barOpened && served[index]) || pouring || heldGlass == null || IsGuidePlaying || index != ExpectedBeerGlass)
            return;

        // 원래 잔의 자식 메시 오프셋을 고려하여 잔 바닥이 표식 위에 오도록 정렬합니다.
        Vector3 slot = serviceMarker.transform.TransformPoint(new Vector3(index == 0 ? -0.38f : 0.38f, 0f, 0f));
        heldGlass.transform.SetParent(originalParent, false);
        heldGlass.transform.localRotation = originalLocalRotation;
        heldGlass.transform.localScale = originalLocalScale;
        heldGlass.transform.position = slot;
        Renderer[] renderers = heldGlass.GetComponentsInChildren<Renderer>();
        if (renderers.Length > 0)
        {
            Bounds bounds = renderers[0].bounds;
            foreach (Renderer renderer in renderers)
                bounds.Encapsulate(renderer.bounds);
            heldGlass.transform.position += new Vector3(slot.x - bounds.center.x,
                slot.y - bounds.min.y, slot.z - bounds.center.z);
        }

        // 서빙된 잔은 다시 집거나 중복 제출할 수 없습니다.
        if (!barOpened) served[index] = true;
        if (sounds != null) sounds.PlayResult(true);
        serviceRings[index].sharedMaterial = completedMaterial;
        heldGlass = null;
        heldColliders = null;
        if (barOpened && night != null) { night.CompleteBeer(); return; }
        prompt = TaskCompleted ? "Order complete! Both beers served." : "Beer served! Prepare the other glass.";
        ShowAction(TaskCompleted ? "BEER TASK COMPLETE" : "BEER SERVED - 1 / 2",
            TaskCompleted ? "Both glasses served. Walk around the bar to the rear cocktail table." : "Schooner served. Listen to the pint instruction.", 3f);
        if (!TaskCompleted) QueueBeerGuide(2, true);
    }

    void CreateServiceMarker()
    {
        BoxCollider desk = null;
        foreach (GameObject root in gameObject.scene.GetRootGameObjects())
        {
            foreach (BoxCollider collider in root.GetComponentsInChildren<BoxCollider>())
            {
                if (collider.gameObject.activeInHierarchy && collider.name == "BeerStage_BarCounterTop")
                {
                    desk = collider;
                    break;
                }
            }
            if (desk != null)
                break;
        }
        if (desk == null)
        {
            Debug.LogError("BeerGlassPour: BeerStage_BarCounterTop 데스크를 찾지 못해 서빙 표식을 만들 수 없습니다.");
            return;
        }

        serviceDesk = desk;
        Shader shader = Shader.Find("Universal Render Pipeline/Unlit");
        if (shader == null) shader = Shader.Find("Unlit/Color");
        markerMaterial = new Material(shader) { color = new Color(0.1f, 0.85f, 1f) };
        completedMaterial = new Material(shader) { color = new Color(0.25f, 1f, 0.35f) };
        liquidMaterial = new Material(shader) { color = new Color(1f, 0.62f, 0.06f) };
        foamMaterial = new Material(shader) { color = new Color(1f, 0.95f, 0.8f) };

        // 현재 씬의 실제 데스크 앞쪽에 생성합니다. 원본 Transform은 변경하지 않습니다.
        serviceMarker = new GameObject("BeerService_Marker_Runtime");
        UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(serviceMarker, gameObject.scene);
        serviceMarker.transform.position = desk.transform.TransformPoint(desk.center
            + new Vector3(0f, desk.size.y * 0.5f, -desk.size.z * 0.25f)) + Vector3.up * 0.02f;
        // 탭 옆에서 다음 목표를 바로 볼 수 있도록 표식을 가까이 둡니다.
        if (beerNozzle != null)
        {
            float left = desk.transform.TransformPoint(desk.center - Vector3.right * desk.size.x * 0.5f).x;
            float right = desk.transform.TransformPoint(desk.center + Vector3.right * desk.size.x * 0.5f).x;
            Vector3 position = serviceMarker.transform.position;
            position.x = Mathf.Clamp(beerNozzle.position.x - 1f, Mathf.Min(left, right) + 0.8f,
                Mathf.Max(left, right) - 0.8f);
            serviceMarker.transform.position = position;
        }
        BoxCollider zone = serviceMarker.AddComponent<BoxCollider>();
        zone.isTrigger = true;
        zone.center = new Vector3(0f, 0.18f, 0f);
        zone.size = new Vector3(1.5f, 0.4f, 0.7f);

        for (int index = 0; index < 2; index++)
        {
            GameObject ringObject = new GameObject(index == 0 ? "Schooner_ServeSlot" : "Pint_ServeSlot");
            ringObject.transform.SetParent(serviceMarker.transform, false);
            ringObject.transform.localPosition = new Vector3(index == 0 ? -0.38f : 0.38f, 0f, 0f);
            LineRenderer ring = ringObject.AddComponent<LineRenderer>();
            ring.useWorldSpace = false;
            ring.loop = true;
            ring.positionCount = 48;
            ring.widthMultiplier = 0.025f;
            ring.sharedMaterial = markerMaterial;
            ring.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            ring.receiveShadows = false;
            for (int segment = 0; segment < 48; segment++)
            {
                float angle = segment * Mathf.PI * 2f / 48;
                ring.SetPosition(segment, new Vector3(Mathf.Cos(angle) * 0.27f, 0f, Mathf.Sin(angle) * 0.27f));
            }
            serviceRings[index] = ring;
        }
        serviceMarker.SetActive(false);
    }

    void CreateFilledVisual(int index)
    {
        if (liquidMaterial == null || filledVisuals[index] != null)
            return;
        Renderer outer = heldGlass.GetComponentInChildren<Renderer>();
        if (outer == null) return;
        GameObject liquid = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
        liquid.name = "FilledBeer_Runtime";
        liquid.transform.SetParent(outer.transform, false);
        liquid.transform.localPosition = new Vector3(0f, -0.2f, 0f);
        liquid.transform.localScale = new Vector3(0.78f, 0.7f, 0.78f);
        Collider liquidCollider = liquid.GetComponent<Collider>();
        liquidCollider.enabled = false;
        Destroy(liquidCollider);
        liquid.GetComponent<Renderer>().sharedMaterial = liquidMaterial;
        GameObject foam = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
        foam.name = "BeerFoam_Runtime";
        foam.transform.SetParent(liquid.transform, false);
        foam.transform.localPosition = new Vector3(0f, 1f, 0f);
        foam.transform.localScale = new Vector3(1f, 0.055f, 1f);
        Collider foamCollider = foam.GetComponent<Collider>();
        foamCollider.enabled = false;
        Destroy(foamCollider);
        foam.GetComponent<Renderer>().sharedMaterial = foamMaterial;
        filledVisuals[index] = liquid;
    }

    void OnDisable()
    {
        if (stationBeacon != null) stationBeacon.Hide();
        if (night != null) night.Suspend();
        CancelBeerGuide();
        if (sounds != null) sounds.StopAll();
    }

    void OnApplicationFocus(bool hasFocus)
    {
        if (sounds != null) sounds.SetFocus(hasFocus);
    }

    void OnApplicationPause(bool paused)
    {
        if (sounds != null) sounds.SetApplicationPause(paused);
    }

    void OnDestroy()
    {
        if (stationBeacon != null) stationBeacon.Dispose();
        CancelBeerGuide();
        if (beerGuidance != null) beerGuidance.Dispose();
        if (night != null) night.Dispose();
        if (practice != null) practice.Dispose();
        if (sounds != null) sounds.Dispose();
        if (recipeCards != null) recipeCards.Dispose();
        if (cocktailEquipment != null) cocktailEquipment.Dispose();
        if (serviceMarker != null) Destroy(serviceMarker);
        if (beerStream != null) Destroy(beerStream);
        if (holdPoint != null) Destroy(holdPoint.gameObject);
        foreach (GameObject visual in filledVisuals)
            if (visual != null) Destroy(visual);
        if (markerMaterial != null) Destroy(markerMaterial);
        if (completedMaterial != null) Destroy(completedMaterial);
        if (liquidMaterial != null) Destroy(liquidMaterial);
        if (foamMaterial != null) Destroy(foamMaterial);
        if (streamMaterial != null) Destroy(streamMaterial);
    }

    bool PressedLeftClick()
    {
#if ENABLE_INPUT_SYSTEM
        return Mouse.current != null
            && Mouse.current.leftButton.wasPressedThisFrame;
#else
        return Input.GetMouseButtonDown(0);
#endif
    }

    bool PressedInteract()
    {
#if ENABLE_INPUT_SYSTEM
        return Keyboard.current != null
            && Keyboard.current.eKey.wasPressedThisFrame;
#else
        return Input.GetKeyDown(KeyCode.E);
#endif
    }

    bool PressedRecipeClose()
    {
#if ENABLE_INPUT_SYSTEM
        return Keyboard.current != null && Keyboard.current.escapeKey.wasPressedThisFrame;
#else
        return Input.GetKeyDown(KeyCode.Escape);
#endif
    }

    void OnGUI()
    {
        if (practice != null && practice.IsActive)
        {
            practice.Draw();
            return;
        }
        if (uniform == null || !uniform.ShiftCompleted)
            return;

        if (barOpened && night != null)
        {
            night.Draw();
            InteractionPromptUI.Draw(prompt);
            DrawActionFeedback();
            return;
        }

        if (recipeCards != null && recipeCards.IsOpen)
        {
            recipeCards.DrawOverlay();
            return;
        }

        if (textStyle == null)
        {
            textStyle = new GUIStyle(GUI.skin.label);
            textStyle.fontSize = 20;
            textStyle.alignment = TextAnchor.MiddleCenter;
            textStyle.wordWrap = true;
            textStyle.normal.textColor = Color.white;
        }

        if (IsGuidePlaying)
        {
            string heading = pendingBeerInstruction == 0 ? "SCHOONER FIRST" : pendingBeerInstruction == 1
                ? "WRONG GLASS" : pendingBeerInstruction == 2 ? "NEXT: PINT" : "COCKTAIL STATION";
            float width = Mathf.Min(640f, Screen.width - 32f);
            Rect guidePanel = new Rect((Screen.width - width) * 0.5f, Screen.height * 0.5f - 70f, width, 140f);
            GUI.Box(guidePanel, "");
            GUI.Label(guidePanel, heading + "\nListen to the guide...\nYou can move. Interact after the guide ends.", textStyle);
            return;
        }

        int count = (served[0] ? 1 : 0) + (served[1] ? 1 : 0);
        Rect taskArea = new Rect(Mathf.Max(15f, Screen.width - 405f), 15f, 390f, 105f);
        GUI.Box(taskArea, "");
        GUI.Label(taskArea, barOpened ? "BAR OPEN\nAll training trials complete." : TaskCompleted
            ? "TASK COMPLETE!\nBoth beers served."
            : "SERVE TWO BEERS  " + count + "/2\nSchooner: " + GlassStatus(0) + "   Pint: " + GlassStatus(1), textStyle);

        string instruction;
        if (barOpened)
            instruction = "Training complete. The bar is open.";
        else if (cocktailEquipment != null && cocktailEquipment.IsHolding)
            instruction = "COCKTAIL TOOLS: " + cocktailEquipment.HeldName + "\nLEFT CLICK to put it back on the table";
        else if (TaskCompleted && !cocktailBriefingCompleted)
            instruction = "Both beers served. Walk around the bar to the rear cocktail table for your briefing.";
        else if (TaskCompleted)
            instruction = "BEER TASK COMPLETE! Choose a recipe card on the cocktail table.";
        else if (pouring)
            instruction = "2. POURING BEER...";
        else if (!beerIntroStarted)
            instruction = "Walk to the beer tap. Your first instruction plays when you arrive.";
        else if (heldGlass == null)
            instruction = "1. Pick up the " + (ExpectedBeerGlass == 0 ? "schooner" : "pint") + " with LEFT CLICK";
        else if (!filled[HeldGlassIndex()])
            instruction = "2. Aim at the beer tap and press E to fill the glass";
        else
            instruction = "3. BEER READY! Aim at the glowing SERVE spot and LEFT CLICK to place";

        float panelWidth = Mathf.Min(650f, Screen.width - 30f);
        Rect instructionArea = new Rect((Screen.width - panelWidth) * 0.5f, 130f, panelWidth, 85f);
        GUI.Box(instructionArea, "");
        bool cocktailFocus = TaskCompleted || (cocktailEquipment != null && cocktailEquipment.IsHolding);
        GUI.Label(instructionArea, (cocktailFocus ? "COCKTAIL STATION\n" : "PICK UP > POUR > SERVE\n") + instruction, textStyle);
        if (cocktailEquipment != null) cocktailEquipment.DrawLabels(textStyle);

        if (serviceMarker != null && serviceMarker.activeInHierarchy)
        {
            Vector3 screen = playerCamera.WorldToScreenPoint(serviceMarker.transform.position + Vector3.up * 0.5f);
            bool readyToServe = heldGlass != null && filled[HeldGlassIndex()] && !pouring;
            bool onScreen = screen.z > 0f && screen.x >= 0f && screen.x <= Screen.width
                && screen.y >= 0f && screen.y <= Screen.height;
            if (onScreen || readyToServe)
            {
                if (screen.z < 0f)
                {
                    screen.x = Screen.width - screen.x;
                    screen.y = Screen.height - screen.y;
                }
                float labelX = Mathf.Clamp(screen.x - 150f, 5f, Mathf.Max(5f, Screen.width - 305f));
                float labelY = Mathf.Clamp(Screen.height - screen.y - 25f, 225f,
                    Mathf.Max(225f, Screen.height - 90f));
                Rect markerArea = new Rect(labelX, labelY, 300f, 65f);
                GUI.Box(markerArea, "");
                GUI.Label(markerArea, TaskCompleted ? "SERVING COMPLETE"
                    : !onScreen ? "TURN TOWARD SERVE"
                    : readyToServe ? "SERVE HERE\nAim here + LEFT CLICK"
                    : "SERVE HERE  " + count + "/2", textStyle);
            }
        }

        InteractionPromptUI.Draw(prompt);
        DrawActionFeedback();
    }

    void ShowAction(string title, string detail, float duration = 2.2f)
    {
        actionTitle = title; actionDetail = detail; actionUntil = Time.unscaledTime + duration;
    }

    void DrawActionFeedback()
    {
        if (Time.unscaledTime >= actionUntil) return;
        if (actionTitleStyle == null)
        {
            actionTitleStyle = new GUIStyle(GUI.skin.label) { fontSize = 24, fontStyle = FontStyle.Bold, alignment = TextAnchor.MiddleLeft, padding = new RectOffset(0, 0, 0, 0) };
            actionTitleStyle.normal.textColor = new Color(0.8f, 1f, 0.88f);
            actionDetailStyle = new GUIStyle(GUI.skin.label) { fontSize = 17, wordWrap = true, alignment = TextAnchor.UpperLeft, padding = new RectOffset(0, 0, 0, 0) };
            actionDetailStyle.normal.textColor = Color.white;
        }
        float width = Mathf.Min(640f, Screen.width - 32f);
        // 커진 조준 안내와 분리해 완료 피드백은 화면 아래쪽에 표시합니다.
        Rect panel = new Rect((Screen.width - width) * 0.5f, Screen.height - 116f, width, 88f);
        Color old = GUI.color;
        GUI.color = new Color(0.025f, 0.13f, 0.11f, 0.96f); GUI.DrawTexture(panel, Texture2D.whiteTexture);
        GUI.color = new Color(0.4f, 0.9f, 0.6f); GUI.DrawTexture(new Rect(panel.x, panel.y, 5f, panel.height), Texture2D.whiteTexture);
        GUI.color = old;
        GUI.Label(new Rect(panel.x + 18f, panel.y + 7f, width - 36f, 33f), actionTitle, actionTitleStyle);
        GUI.Label(new Rect(panel.x + 18f, panel.y + 43f, width - 36f, 40f), actionDetail, actionDetailStyle);
    }

    void OpenBar()
    {
        if (!AllTrialsComplete || barOpened) return;
        if (practice != null && practice.IsActive) practice.Dispose();
        if (recipeCards != null) recipeCards.Close();
        if (serviceDesk == null || serviceMarker == null)
        {
            ShowAction("CANNOT OPEN", "The bar counter / serving marker is missing.", 4f);
            return;
        }
        barOpened = true;
        if (recipeCards != null) recipeCards.SetAvailable(false);
        night = new NightService(this);
        // OPEN 클릭은 메뉴를 닫고 즉시 일인칭 마우스 시점으로 돌아갑니다. 전환용 입력 잠금은 없습니다.
        Cursor.lockState = CursorLockMode.Locked; Cursor.visible = false;
        ShowAction("BAR OPEN / NIGHT SERVICE", "Customers will arrive shortly. Observe each guest and choose how to respond.", 4f);
    }

    void DrawTrialChecks(Rect area, int recipe, GUIStyle labelStyle)
    {
        float cell = area.width / 3f;
        for (int index = 0; index < 3; index++)
        {
            bool done = passedTrials[recipe] > index;
            Rect box = new Rect(area.x + index * cell + 3f, area.y + 5f, 22f, 22f);
            Color old = GUI.color;
            GUI.color = done ? new Color(0.22f, 0.55f, 0.36f) : new Color(0.5f, 0.58f, 0.53f, 0.35f);
            GUI.DrawTexture(box, Texture2D.whiteTexture); GUI.color = old;
            if (done)
            {
                DrawCheckStroke(new Vector2(box.x + 4f, box.y + 11f), new Vector2(box.x + 9f, box.y + 16f));
                DrawCheckStroke(new Vector2(box.x + 9f, box.y + 16f), new Vector2(box.x + 18f, box.y + 6f));
            }
            GUI.Label(new Rect(box.x + 30f, area.y + 3f, cell - 35f, 26f), "Trial " + (index + 1), labelStyle);
        }
    }

    void DrawCheckStroke(Vector2 start, Vector2 end)
    {
        Matrix4x4 saved = GUI.matrix;
        Color old = GUI.color;
        Vector2 delta = end - start;
        GUIUtility.RotateAroundPivot(Mathf.Atan2(delta.y, delta.x) * Mathf.Rad2Deg, start);
        GUI.color = Color.white;
        GUI.DrawTexture(new Rect(start.x, start.y - 1f, delta.magnitude, 2.5f), Texture2D.whiteTexture);
        GUI.color = old; GUI.matrix = saved;
    }

    void BeginPractice(int recipe)
    {
        if (barOpened || !cocktailBriefingCompleted || IsGuidePlaying) return;
        recipeCards.Close();
        if (practice != null) practice.Dispose();
        practice = new CocktailPractice(this, recipe);
    }

    string GlassStatus(int index)
    {
        return served[index] ? "SERVED" : filled[index] ? "READY" : "EMPTY";
    }

    // 동기화 대상인 이 파일에 포함해 새 씬/프리팹/Inspector 연결 없이 장비를 만듭니다.
    private sealed class CocktailEquipment
    {
        private readonly BeerGlassPour owner;
        public BoxCollider Table { get; private set; }
        private GameObject root;
        private readonly GameObject[] tools = new GameObject[3];
        private readonly Vector3[] slots = new Vector3[3];
        private readonly string[] names = { "Large shaker tin", "Small shaker tin", "Jigger: 1 oz / 0.5 oz" };
        private readonly float[] heights = { 0.27f, 0.20f, 0.115f };
        private readonly System.Collections.Generic.List<Mesh> meshes = new System.Collections.Generic.List<Mesh>();
        private Material steel;
        private Material rubber;
        private int held = -1;
        public bool IsHolding => held >= 0;
        public string HeldName => IsHolding ? names[held] : "";

        public CocktailEquipment(BeerGlassPour owner)
        {
            this.owner = owner;
            BoxCollider table = null;
            foreach (GameObject sceneRoot in owner.gameObject.scene.GetRootGameObjects())
            {
                foreach (BoxCollider collider in sceneRoot.GetComponentsInChildren<BoxCollider>())
                {
                    if (collider.gameObject.activeInHierarchy && collider.name == "GlassTable_Top")
                    {
                        table = collider;
                        break;
                    }
                }
                if (table != null) break;
            }
            if (table == null)
            {
                Debug.LogError("CocktailEquipment: 뒤쪽 GlassTable_Top 테이블을 찾지 못했습니다.");
                return;
            }
            Table = table;
            Shader shader = Shader.Find("Universal Render Pipeline/Lit");
            if (shader == null) shader = Shader.Find("Standard");
            if (shader == null)
            {
                Debug.LogError("CocktailEquipment: 금속 재질용 셰이더를 찾지 못했습니다.");
                return;
            }
            steel = new Material(shader) { color = new Color(0.72f, 0.78f, 0.82f) };
            steel.SetFloat("_Metallic", 0.85f);
            steel.SetFloat("_Smoothness", 0.78f);
            rubber = new Material(shader) { color = new Color(0.025f, 0.045f, 0.05f) };
            rubber.SetFloat("_Smoothness", 0.2f);

            root = new GameObject("CocktailEquipment_Runtime");
            UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root, owner.gameObject.scene);
            root.transform.position = table.transform.TransformPoint(table.center
                + new Vector3(0f, table.size.y * 0.5f, -table.size.z * 0.12f)) + Vector3.up * 0.012f;
            root.transform.rotation = table.transform.rotation;
            GameObject mat = GameObject.CreatePrimitive(PrimitiveType.Cube);
            mat.name = "Cocktail_BarMat";
            mat.transform.SetParent(root.transform, false);
            mat.transform.localPosition = new Vector3(0f, -0.006f, 0f);
            mat.transform.localScale = new Vector3(1.65f, 0.012f, 0.42f);
            mat.GetComponent<Renderer>().sharedMaterial = rubber;
            Collider matCollider = mat.GetComponent<Collider>();
            matCollider.enabled = false;
            UnityEngine.Object.Destroy(matCollider);

            CreateTin(0, 0.041f, 0.055f);
            CreateTin(1, 0.034f, 0.047f);
            CreateJigger();
        }

        private GameObject CreateTool(int index, string objectName, float diameter)
        {
            GameObject tool = new GameObject(objectName);
            tool.transform.SetParent(root.transform, false);
            slots[index] = new Vector3((index - 1) * 0.48f, 0f, 0f);
            tool.transform.localPosition = slots[index];
            BoxCollider collider = tool.AddComponent<BoxCollider>();
            collider.center = Vector3.up * heights[index] * 0.5f;
            collider.size = new Vector3(diameter, heights[index], diameter);
            tools[index] = tool;
            return tool;
        }

        private void CreateTin(int index, float bottomRadius, float topRadius)
        {
            float height = heights[index];
            GameObject tool = CreateTool(index, index == 0 ? "Shaker_LargeTin" : "Shaker_SmallTin", topRadius * 2f);
            // 외벽 → 둥근 테두리 → 내벽 → 바닥으로 이어지는 열린 컵입니다.
            Vector2[] profile = {
                new Vector2(0f, 0f), new Vector2(bottomRadius, 0f),
                new Vector2(bottomRadius + 0.002f, 0.012f),
                new Vector2(topRadius - 0.001f, height - 0.008f),
                new Vector2(topRadius, height - 0.003f), new Vector2(topRadius, height),
                new Vector2(topRadius - 0.003f, height),
                new Vector2(bottomRadius - 0.001f, 0.008f),
                new Vector2(0f, 0.006f), new Vector2(0f, 0f)
            };
            AddLathedMesh(tool.transform, "HollowStainlessTin", profile);
        }

        private void CreateJigger()
        {
            GameObject tool = CreateTool(2, "Jigger_1oz_0.5oz", 0.076f);
            GameObject large = new GameObject("Cup_1oz");
            large.transform.SetParent(tool.transform, false);
            large.transform.localPosition = new Vector3(0f, 0.05f, 0f);
            AddLathedMesh(large.transform, "OneOunceCup", new[] {
                new Vector2(0f, 0f), new Vector2(0.012f, 0f),
                new Vector2(0.018f, 0.012f), new Vector2(0.036f, 0.061f),
                new Vector2(0.036f, 0.065f), new Vector2(0.033f, 0.065f),
                new Vector2(0.015f, 0.013f), new Vector2(0f, 0.006f), new Vector2(0f, 0f)
            });
            GameObject small = new GameObject("Cup_0.5oz");
            small.transform.SetParent(tool.transform, false);
            small.transform.localPosition = new Vector3(0f, 0.05f, 0f);
            small.transform.localRotation = Quaternion.Euler(180f, 0f, 0f);
            AddLathedMesh(small.transform, "HalfOunceCup", new[] {
                new Vector2(0f, 0f), new Vector2(0.012f, 0f),
                new Vector2(0.028f, 0.046f), new Vector2(0.028f, 0.05f),
                new Vector2(0.025f, 0.05f), new Vector2(0.009f, 0.009f),
                new Vector2(0f, 0.006f), new Vector2(0f, 0f)
            });
        }

        private void AddLathedMesh(Transform parent, string name, Vector2[] profile)
        {
            const int segments = 64;
            Vector3[] vertices = new Vector3[profile.Length * (segments + 1)];
            int[] triangles = new int[(profile.Length - 1) * segments * 6];
            int triangle = 0;
            for (int row = 0; row < profile.Length; row++)
            {
                for (int segment = 0; segment <= segments; segment++)
                {
                    float angle = segment * Mathf.PI * 2f / segments;
                    int vertex = row * (segments + 1) + segment;
                    vertices[vertex] = new Vector3(Mathf.Cos(angle) * profile[row].x,
                        profile[row].y, Mathf.Sin(angle) * profile[row].x);
                    if (row == profile.Length - 1 || segment == segments) continue;
                    int next = vertex + segments + 1;
                    triangles[triangle++] = vertex;
                    triangles[triangle++] = next;
                    triangles[triangle++] = next + 1;
                    triangles[triangle++] = vertex;
                    triangles[triangle++] = next + 1;
                    triangles[triangle++] = vertex + 1;
                }
            }
            Mesh mesh = new Mesh { name = name };
            mesh.vertices = vertices;
            mesh.triangles = triangles;
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            meshes.Add(mesh);
            GameObject surface = new GameObject(name);
            surface.transform.SetParent(parent, false);
            surface.AddComponent<MeshFilter>().sharedMesh = mesh;
            surface.AddComponent<MeshRenderer>().sharedMaterial = steel;
        }

        public bool HandleInput(bool clicked, out string prompt)
        {
            prompt = "";
            if (root == null) return false;
            if (IsHolding)
            {
                prompt = "LEFT CLICK - Put " + names[held] + " back on the table";
                if (clicked)
                {
                    Transform tool = tools[held].transform;
                    tool.SetParent(root.transform, false);
                    tool.localPosition = slots[held];
                    tool.localRotation = Quaternion.identity;
                    tool.GetComponent<Collider>().enabled = true;
                    owner.ShowAction("TOOL RETURNED", names[held] + " is back on the table.");
                    held = -1;
                }
                return true;
            }
            Ray ray = owner.playerCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
            if (!Physics.Raycast(ray, out RaycastHit hit, owner.pickupDistance,
                Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore)) return false;
            for (int index = 0; index < tools.Length; index++)
            {
                if (tools[index] == null || !hit.transform.IsChildOf(tools[index].transform)) continue;
                prompt = "LEFT CLICK - Pick up " + names[index];
                if (clicked)
                {
                    held = index;
                    Transform tool = tools[index].transform;
                    tool.GetComponent<Collider>().enabled = false;
                    tool.SetParent(owner.playerCamera.transform, false);
                    tool.localPosition = new Vector3(0.24f, -0.3f, 0.65f);
                    tool.localRotation = Quaternion.Euler(-12f, 0f, 0f);
                    owner.ShowAction("TOOL PICKED UP", names[index] + " selected.");
                }
                return true;
            }
            return false;
        }

        public void DrawLabels(GUIStyle style)
        {
            if (root == null) return;
            for (int index = 0; index < tools.Length; index++)
            {
                if (tools[index] == null || held == index) continue;
                Vector3 point = tools[index].transform.position + Vector3.up * (heights[index] + 0.06f);
                if (Vector3.Distance(owner.playerCamera.transform.position, point) > 3.5f) continue;
                Vector3 screen = owner.playerCamera.WorldToScreenPoint(point);
                if (screen.z <= 0f) continue;
                GUI.Label(new Rect(screen.x - 115f, Screen.height - screen.y - 20f, 230f, 45f), names[index], style);
            }
        }

        public void Dispose()
        {
            if (IsHolding && tools[held] != null) UnityEngine.Object.Destroy(tools[held]);
            if (root != null) UnityEngine.Object.Destroy(root);
            foreach (Mesh mesh in meshes) UnityEngine.Object.Destroy(mesh);
            if (steel != null) UnityEngine.Object.Destroy(steel);
            if (rubber != null) UnityEngine.Object.Destroy(rubber);
        }
    }

    // 전용 효과음 소스만 관리합니다. 이동·입력·판정·안내 음성은 변경하지 않습니다.
    private enum ActionSound { BeerPour, Complete, Failure, DrinkPour, Ice, Shake, Stir }

    private sealed class BeerGuidance
    {
        private readonly GameObject root;
        private readonly AudioSource source;
        private readonly AudioClip[] clips = new AudioClip[4];
        public BeerGuidance(BeerGlassPour owner)
        {
            root = new GameObject("BeerGuidance_Runtime");
            root.transform.SetParent(owner.transform, false);
            source = root.AddComponent<AudioSource>();
            source.playOnAwake = false;
            source.loop = false;
            source.spatialBlend = 0f;
            for (int index = 0; index < clips.Length; index++)
            {
                try
                {
                    byte[] pcm;
                    using (var input = new System.IO.MemoryStream(System.Convert.FromBase64String(packedPcm[index])))
                    using (var unzip = new System.IO.Compression.GZipStream(input, System.IO.Compression.CompressionMode.Decompress))
                    using (var output = new System.IO.MemoryStream())
                    {
                        unzip.CopyTo(output);
                        pcm = output.ToArray();
                    }
                    if (pcm.Length != sampleCounts[index] * 2)
                        throw new System.IO.InvalidDataException("Beer guide sample count does not match.");
                    float[] samples = new float[sampleCounts[index]];
                    for (int sample = 0; sample < samples.Length; sample++)
                        samples[sample] = unchecked((short)(pcm[sample * 2] | pcm[sample * 2 + 1] << 8)) / 32768f;
                    clips[index] = AudioClip.Create("BeerGuide_" + index, samples.Length, 1, 44100, false);
                    if (clips[index] == null || !clips[index].SetData(samples, 0))
                        throw new System.IO.InvalidDataException("Could not create beer guide clip.");
                }
                catch (System.Exception exception)
                {
                    if (clips[index] != null) UnityEngine.Object.Destroy(clips[index]);
                    clips[index] = null;
                    Debug.LogWarning("Beer guide unavailable; gameplay will continue. " + exception.Message);
                }
            }
        }

        public IEnumerator Play(int instruction)
        {
            if (source == null || !source.isActiveAndEnabled || clips[instruction] == null) yield break;
            source.clip = clips[instruction];
            source.Play();
            float deadline = Time.realtimeSinceStartup + source.clip.length + 1f;
            yield return null;
            while (source != null && source.isActiveAndEnabled && source.isPlaying)
            {
                if (Time.realtimeSinceStartup >= deadline) { source.Stop(); yield break; }
                yield return null;
            }
        }

        public void Stop() { if (source != null) source.Stop(); }
        public void Dispose()
        {
            Stop();
            if (root != null) UnityEngine.Object.Destroy(root);
            foreach (AudioClip clip in clips) if (clip != null) UnityEngine.Object.Destroy(clip);
        }

        // 첨부 원본은 Tools/AudioSources에 보존합니다. 기존 Mac 스크립트 동기화로 음성도 전달합니다.
        private static readonly int[] sampleCounts = { 139392, 129024, 139392, 498816 };
        private static readonly string[] packedPcm = {
            "",
            "",
            "",
            ""
        };
    }

    private sealed class ActionSounds
    {
        private readonly BeerGlassPour owner;
        private readonly GameObject root;
        private readonly AudioSource continuousSource, effectSource, resultSource;
        private readonly AudioClip[] clips = new AudioClip[7];
        private readonly bool[] unavailable = new bool[7];
        private int continuousKind = -1;
        private bool continuousPaused, applicationPaused, disposed;
        private bool focused;

        public ActionSounds(BeerGlassPour owner)
        {
            this.owner = owner;
            focused = Application.isFocused;
            root = new GameObject("ActionSounds_Runtime");
            root.transform.SetParent(owner.transform, false);
            continuousSource = CreateSource(true);
            effectSource = CreateSource(false);
            resultSource = CreateSource(false);
            // 시작 안내 화면에서 한 번 복원해 실제 동작 프레임의 디코딩을 피합니다.
            for (int index = 0; index < clips.Length; index++) GetClip((ActionSound)index);
        }

        private AudioSource CreateSource(bool loop)
        {
            AudioSource source = root.AddComponent<AudioSource>();
            source.playOnAwake = false;
            source.loop = loop;
            source.spatialBlend = 0f;
            source.dopplerLevel = 0f;
            return source;
        }

        private bool CanPlay => !disposed && owner != null && owner.isActiveAndEnabled
            && focused && !applicationPaused && !AudioListener.pause;

        private AudioClip GetClip(ActionSound sound)
        {
            int index = (int)sound;
            if (clips[index] != null || unavailable[index]) return clips[index];
            try
            {
                byte[] pcm;
                using (var input = new System.IO.MemoryStream(System.Convert.FromBase64String(packedPcm[index])))
                using (var unzip = new System.IO.Compression.GZipStream(input, System.IO.Compression.CompressionMode.Decompress))
                using (var output = new System.IO.MemoryStream())
                {
                    unzip.CopyTo(output);
                    pcm = output.ToArray();
                }
                if (pcm.Length != sampleCounts[index] * 2)
                    throw new System.IO.InvalidDataException("Action sound sample count does not match.");
                float[] samples = new float[sampleCounts[index]];
                for (int sample = 0; sample < samples.Length; sample++)
                    samples[sample] = unchecked((short)(pcm[sample * 2] | pcm[sample * 2 + 1] << 8)) / 32768f;
                clips[index] = AudioClip.Create("ActionSound_" + sound, samples.Length, 1, sampleRates[index], false);
                if (clips[index] == null || !clips[index].SetData(samples, 0))
                    throw new System.IO.InvalidDataException("Could not create action sound clip.");
                return clips[index];
            }
            catch (System.Exception exception)
            {
                if (clips[index] != null) UnityEngine.Object.Destroy(clips[index]);
                clips[index] = null;
                unavailable[index] = true;
                Debug.LogWarning("Action sound unavailable: " + sound + ". Gameplay will continue. " + exception.Message);
                return null;
            }
        }

        public void PlayContinuous(ActionSound sound)
        {
            if (!CanPlay || continuousSource == null || !continuousSource.isActiveAndEnabled)
            {
                StopContinuous();
                return;
            }
            if (continuousKind != (int)sound)
            {
                StopContinuous();
                AudioClip clip = GetClip(sound);
                if (clip == null) return;
                continuousKind = (int)sound;
                continuousSource.clip = clip;
                continuousSource.volume = volumes[(int)sound];
                continuousSource.Play();
            }
            else if (continuousPaused)
            {
                continuousSource.UnPause();
                continuousPaused = false;
            }
            else if (!continuousSource.isPlaying) continuousSource.Play();
        }

        public void PauseContinuous()
        {
            if (continuousSource == null || continuousKind < 0 || continuousPaused) return;
            continuousSource.Pause();
            continuousPaused = true;
        }

        public void StopContinuous()
        {
            if (continuousSource != null) { continuousSource.Stop(); continuousSource.clip = null; }
            continuousKind = -1;
            continuousPaused = false;
        }

        public void PlayIce()
        {
            if (!CanPlay || effectSource == null || !effectSource.isActiveAndEnabled) return;
            AudioClip clip = GetClip(ActionSound.Ice);
            if (clip != null) effectSource.PlayOneShot(clip, volumes[(int)ActionSound.Ice]);
        }

        public void PlayResult(bool success)
        {
            StopAll();
            if (!CanPlay || resultSource == null || !resultSource.isActiveAndEnabled) return;
            ActionSound sound = success ? ActionSound.Complete : ActionSound.Failure;
            AudioClip clip = GetClip(sound);
            if (clip == null) return;
            resultSource.clip = clip;
            resultSource.volume = volumes[(int)sound];
            resultSource.Play();
        }

        public IEnumerator WaitForResult()
        {
            float duration = resultSource != null && resultSource.clip != null ? resultSource.clip.length : 0f;
            float deadline = Time.realtimeSinceStartup + duration + 1f;
            yield return null;
            while (!disposed && resultSource != null && resultSource.isActiveAndEnabled && resultSource.isPlaying)
            {
                if (Time.realtimeSinceStartup >= deadline) { resultSource.Stop(); yield break; }
                yield return null;
            }
        }

        public void StopAll()
        {
            StopContinuous();
            if (effectSource != null) effectSource.Stop();
            if (resultSource != null) resultSource.Stop();
        }

        public void SetFocus(bool hasFocus)
        {
            focused = hasFocus;
            if (!hasFocus) StopAll();
        }

        public void SetApplicationPause(bool paused)
        {
            applicationPaused = paused;
            if (paused) StopAll();
        }

        public void Dispose()
        {
            if (disposed) return;
            StopAll();
            disposed = true;
            if (root != null) UnityEngine.Object.Destroy(root);
            foreach (AudioClip clip in clips) if (clip != null) UnityEngine.Object.Destroy(clip);
        }

        // Tools/AudioSources 원본에서 선행 무음만 제거한 mono PCM, 원본 샘플레이트 유지.
        // gzip/base64 PCM을 기존 스크립트 동기화로 전달하므로 새 Inspector 연결이 필요 없습니다.
        private static readonly int[] sampleRates = { 24000, 44100, 48000, 44100, 44100, 24000, 24000 };
        private static readonly int[] sampleCounts = { 721155, 79306, 82484, 201211, 29012, 69349, 266885 };
        private static readonly float[] volumes = { 0.8f, 0.8f, 0.45f, 0.85f, 0.9f, 0.75f, 0.8f };
        private static readonly string[] packedPcm = {
            "",
            "",
            "",
            "",
            "",
            "",
            "" // Stir
        };
    }

    // 영업 상태는 기존 훈련과 분리합니다. 씬/프리팹 참조 없이 기존 카운터를 사용합니다.
    private sealed class NightService
    {
        private enum GuestKind { Regular, CheckID, Intoxicated }
        private enum State { Waiting, Arriving, Screening, Preparing, Receiving, Leaving }
        private readonly BeerGlassPour owner;
        private readonly GameObject root;
        private GameObject guest, receivedDrink;
        private Transform leftArm, rightArm, leftLeg, rightLeg;
        private TextMesh guestCaption;
        private State state;
        private GuestKind kind;
        private int order = -1, guestNumber, servedCount, refusedCount, missedCount, encounterIndex;
        private readonly int[] encounters = { 0, 1, 2, 3, 4 }; // 두 맥주/칵테일/ID/취객을 매 묶음에 모두 포함합니다.
        private readonly string[] orderNames = { "Schooner beer", "Pint beer", "Gin & Tonic", "Negroni", "Long Island Iced Tea" };
        private float deadline;
        private Vector3 entrance, aisle, counter, drinkStart;
        private bool atAisle, dialogOpen, idChecked, disposed;
        private CursorLockMode dialogLock;
        private bool dialogCursor;
        private readonly System.Collections.Generic.List<Material> materials = new System.Collections.Generic.List<Material>();
        private readonly System.Collections.Generic.List<Light> dimmedLights = new System.Collections.Generic.List<Light>();
        private readonly System.Collections.Generic.List<float> lightIntensities = new System.Collections.Generic.List<float>();
        private readonly System.Collections.Generic.List<Color> lightColors = new System.Collections.Generic.List<Color>();
        private Material skin, face, dark, shirt, paper, drinkMaterial;
        private const float NightFadeSeconds = 8f;
        private float nightElapsed, skyExposure, skySunSize;
        private readonly Material savedGlobalSkybox, savedSkybox;
        private Material nightSkybox;
        private readonly Skybox cameraSkybox;
        private readonly Material savedCameraSkybox;
        private readonly Color savedSkyColor, savedEquatorColor, savedGroundColor;
        private readonly System.Collections.Generic.List<Light> nightLamps = new System.Collections.Generic.List<Light>();
        private readonly System.Collections.Generic.List<float> lampIntensities = new System.Collections.Generic.List<float>();
        private readonly System.Collections.Generic.List<string> skyColorProperties = new System.Collections.Generic.List<string>();
        private readonly System.Collections.Generic.List<Color> skyColors = new System.Collections.Generic.List<Color>();
        private readonly UnityEngine.Rendering.AmbientMode savedAmbientMode;
        private readonly Color savedAmbient, savedFogColor, savedBackground;
        private readonly float savedAmbientIntensity, savedReflection, savedFogDensity;
        private readonly bool savedFog;
        private readonly FogMode savedFogMode;
        private readonly CameraClearFlags savedClearFlags;
        private GUIStyle titleStyle, bodyStyle, smallStyle, buttonStyle;
        public bool IsDialogOpen => dialogOpen;
        public bool HasBeerOrder => state == State.Preparing && order >= 0 && order < 2;
        public bool HasCocktailOrder => state == State.Preparing && order >= 2;
        public int ExpectedBeerIndex => HasBeerOrder ? order : -1;

        public NightService(BeerGlassPour owner)
        {
            this.owner = owner;
            savedAmbientMode = RenderSettings.ambientMode; savedAmbient = RenderSettings.ambientLight;
            savedAmbientIntensity = RenderSettings.ambientIntensity; savedReflection = RenderSettings.reflectionIntensity;
            savedFog = RenderSettings.fog; savedFogMode = RenderSettings.fogMode;
            savedFogColor = RenderSettings.fogColor; savedFogDensity = RenderSettings.fogDensity;
            savedBackground = owner.playerCamera.backgroundColor; savedClearFlags = owner.playerCamera.clearFlags;
            savedGlobalSkybox = RenderSettings.skybox;
            cameraSkybox = owner.playerCamera.GetComponent<Skybox>();
            savedCameraSkybox = cameraSkybox != null ? cameraSkybox.material : null;
            savedSkybox = cameraSkybox != null && cameraSkybox.enabled && savedCameraSkybox != null ? savedCameraSkybox : savedGlobalSkybox;
            savedSkyColor = RenderSettings.ambientSkyColor; savedEquatorColor = RenderSettings.ambientEquatorColor; savedGroundColor = RenderSettings.ambientGroundColor;
            root = new GameObject("NightService_Runtime");
            UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root, owner.gameObject.scene);
            Bounds bar = owner.serviceDesk.bounds;
            Bounds floor = owner.guideFloor != null ? owner.guideFloor.bounds : new Bounds(bar.center, new Vector3(12f, 0.1f, 10f));
            float ground = floor.max.y;
            counter = new Vector3(owner.serviceMarker.transform.position.x, ground, bar.min.z - 0.52f);
            entrance = new Vector3(floor.center.x, ground, floor.min.z + 0.9f);
            aisle = new Vector3(counter.x, ground, Mathf.Lerp(entrance.z, counter.z, 0.6f));
            skin = MakeMaterial(new Color(0.75f, 0.51f, 0.34f)); dark = MakeMaterial(new Color(0.07f, 0.09f, 0.13f));
            shirt = MakeMaterial(new Color(0.25f, 0.62f, 0.53f));
            face = MakeMaterial(skin.color);
            paper = MakeMaterial(new Color(0.87f, 0.94f, 0.91f), true);
            drinkMaterial = MakeMaterial(new Color(1f, 0.65f, 0.13f), true);
            BeginNightTransition(); ShuffleEncounters();
            owner.ResetServiceGlasses();
            if (owner.serviceMarker != null) owner.serviceMarker.SetActive(false);
            state = State.Waiting; deadline = Time.unscaledTime + 5f;
        }

        private Material MakeMaterial(Color color, bool unlit = false)
        {
            Shader shader = Shader.Find(unlit ? "Universal Render Pipeline/Unlit" : "Universal Render Pipeline/Lit");
            if (shader == null) shader = Shader.Find(unlit ? "Unlit/Color" : "Standard");
            Material material = new Material(shader) { color = color }; materials.Add(material); return material;
        }
        private GameObject Part(string name, PrimitiveType type, Transform parent, Vector3 position, Vector3 scale, Material material)
        {
            GameObject obj = GameObject.CreatePrimitive(type); obj.name = name;
            obj.transform.SetParent(parent, false); obj.transform.localPosition = position; obj.transform.localScale = scale;
            obj.GetComponent<Renderer>().sharedMaterial = material;
            Collider collider = obj.GetComponent<Collider>(); collider.enabled = false; UnityEngine.Object.Destroy(collider);
            return obj;
        }
        private void Lamp(Vector3 position, Color color, float intensity)
        {
            GameObject obj = new GameObject("NightBarLight"); obj.transform.SetParent(root.transform, false); obj.transform.position = position;
            Light light = obj.AddComponent<Light>(); light.type = LightType.Point; light.range = 7f;
            light.intensity = 0f; light.color = color; light.shadows = LightShadows.None;
            nightLamps.Add(light); lampIntensities.Add(intensity);
        }
        private void BeginNightTransition()
        {
            // 원본 하늘 재질은 건드리지 않고 복제본의 색/밝기만 천천히 바꿉니다.
            if (savedSkybox != null)
            {
                nightSkybox = new Material(savedSkybox);
                if (cameraSkybox != null && cameraSkybox.enabled && cameraSkybox.material != null)
                    cameraSkybox.material = nightSkybox;
                else RenderSettings.skybox = nightSkybox;
                string[] names = { "_SkyTint", "_GroundColor", "_Tint" };
                foreach (string name in names)
                    if (nightSkybox.HasProperty(name)) { skyColorProperties.Add(name); skyColors.Add(nightSkybox.GetColor(name)); }
                if (nightSkybox.HasProperty("_Exposure")) skyExposure = nightSkybox.GetFloat("_Exposure");
                if (nightSkybox.HasProperty("_SunSize")) skySunSize = nightSkybox.GetFloat("_SunSize");
            }
            // Trilight는 현재 하늘/수평선/지면 색에서 시작하므로 갑자기 평면 조명으로 바뀌지 않습니다.
            RenderSettings.ambientMode = savedAmbientMode == UnityEngine.Rendering.AmbientMode.Skybox
                ? UnityEngine.Rendering.AmbientMode.Trilight : savedAmbientMode;
            foreach (GameObject sceneRoot in owner.gameObject.scene.GetRootGameObjects())
                foreach (Light light in sceneRoot.GetComponentsInChildren<Light>())
                    if (light.type == LightType.Directional)
                    {
                        dimmedLights.Add(light); lightIntensities.Add(light.intensity); lightColors.Add(light.color);
                    }
            Lamp(owner.serviceDesk.bounds.center + Vector3.up * 2f, new Color(1f, 0.72f, 0.42f), 3f);
            Lamp(entrance + Vector3.up * 2.5f, new Color(0.35f, 0.55f, 1f), 2f);
            if (owner.cocktailEquipment != null && owner.cocktailEquipment.Table != null)
                Lamp(owner.cocktailEquipment.Table.bounds.center + Vector3.up * 1.8f, new Color(1f, 0.78f, 0.53f), 3f);
            GameObject sign = new GameObject("OpenSign"); sign.transform.SetParent(root.transform, false);
            sign.transform.position = new Vector3(owner.serviceDesk.bounds.min.x + 0.9f, owner.serviceDesk.bounds.max.y + 0.7f, owner.serviceDesk.bounds.center.z);
            TextMesh text = sign.AddComponent<TextMesh>(); text.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            text.fontSize = 64; text.characterSize = 0.08f; text.anchor = TextAnchor.MiddleCenter;
            text.text = "OPEN\nNIGHT SERVICE"; text.color = new Color(0.5f, 1f, 0.73f);
            text.GetComponent<Renderer>().sharedMaterial = text.font.material;
            sign.transform.rotation = Quaternion.Euler(0f, 180f, 0f);
        }
        private void TickNightTransition()
        {
            if (nightElapsed >= NightFadeSeconds) return;
            nightElapsed = Mathf.Min(NightFadeSeconds, nightElapsed + Time.unscaledDeltaTime);
            float blend = Mathf.SmoothStep(0f, 1f, nightElapsed / NightFadeSeconds);
            Color nightAmbient = new Color(0.3f, 0.36f, 0.52f);
            owner.playerCamera.backgroundColor = Color.Lerp(savedBackground, new Color(0.012f, 0.022f, 0.065f), blend);
            RenderSettings.ambientLight = Color.Lerp(savedAmbient, nightAmbient, blend);
            RenderSettings.ambientSkyColor = Color.Lerp(savedSkyColor, nightAmbient, blend);
            RenderSettings.ambientEquatorColor = Color.Lerp(savedEquatorColor, nightAmbient * 0.75f, blend);
            RenderSettings.ambientGroundColor = Color.Lerp(savedGroundColor, nightAmbient * 0.45f, blend);
            RenderSettings.ambientIntensity = Mathf.Lerp(savedAmbientIntensity, 0.7f, blend);
            RenderSettings.reflectionIntensity = Mathf.Lerp(savedReflection, 0.35f, blend);
            // 기존 안개 모드와 거리는 유지하고 색만 보간해 모드 전환으로 인한 깜빡임을 피합니다.
            if (savedFog) RenderSettings.fogColor = Color.Lerp(savedFogColor, new Color(0.025f, 0.035f, 0.09f), blend);
            for (int i = 0; i < dimmedLights.Count; i++) if (dimmedLights[i] != null)
            {
                dimmedLights[i].intensity = Mathf.Lerp(lightIntensities[i], 0.22f, blend);
                dimmedLights[i].color = Color.Lerp(lightColors[i], new Color(0.48f, 0.61f, 1f), blend);
            }
            for (int i = 0; i < nightLamps.Count; i++) if (nightLamps[i] != null)
                nightLamps[i].intensity = lampIntensities[i] * blend;
            if (nightSkybox != null)
            {
                for (int i = 0; i < skyColorProperties.Count; i++)
                    nightSkybox.SetColor(skyColorProperties[i], Color.Lerp(skyColors[i], new Color(0.035f, 0.065f, 0.16f), blend));
                if (nightSkybox.HasProperty("_Exposure")) nightSkybox.SetFloat("_Exposure", Mathf.Lerp(skyExposure, 0.12f, blend));
                if (nightSkybox.HasProperty("_SunSize")) nightSkybox.SetFloat("_SunSize", Mathf.Lerp(skySunSize, 0f, blend));
            }
        }
        private void ShuffleEncounters()
        {
            for (int i = encounters.Length - 1; i > 0; i--)
            { int j = Random.Range(0, i + 1); int swap = encounters[i]; encounters[i] = encounters[j]; encounters[j] = swap; }
            encounterIndex = 0;
        }
        private void SpawnGuest()
        {
            if (encounterIndex >= encounters.Length) ShuffleEncounters();
            int encounter = encounters[encounterIndex++];
            kind = encounter == 3 ? GuestKind.CheckID : encounter == 4 ? GuestKind.Intoxicated : GuestKind.Regular;
            order = kind != GuestKind.Regular ? Random.Range(0, 5) : encounter == 2 ? Random.Range(2, 5) : encounter;
            guestNumber++; idChecked = false; atAisle = false;
            guest = new GameObject("Customer_" + guestNumber); guest.transform.SetParent(root.transform, false); guest.transform.position = entrance;
            shirt.color = Color.HSVToRGB(Random.value, 0.45f, 0.75f);
            bool younger = kind == GuestKind.CheckID;
            float headY = younger ? 1.51f : 1.62f;
            face.color = kind == GuestKind.Intoxicated ? new Color(0.87f, 0.31f, 0.27f) : skin.color;
            Part("Body", PrimitiveType.Capsule, guest.transform, Vector3.up * (younger ? 0.99f : 1.03f),
                younger ? new Vector3(0.42f, 0.35f, 0.27f) : new Vector3(0.49f, 0.39f, 0.29f), shirt);
            Part("Head", PrimitiveType.Sphere, guest.transform, Vector3.up * headY, Vector3.one * (younger ? 0.35f : 0.32f), face);
            Part("Hair", PrimitiveType.Sphere, guest.transform, new Vector3(0f, headY + 0.12f, -0.025f), new Vector3(0.34f, 0.12f, 0.3f), dark);
            if (younger)
                Part("Fringe", PrimitiveType.Sphere, guest.transform, new Vector3(0f, headY + 0.09f, 0.1f), new Vector3(0.32f, 0.08f, 0.13f), dark);
            else
                Part("Chin", PrimitiveType.Sphere, guest.transform, new Vector3(0f, headY - 0.10f, 0.10f), new Vector3(0.17f, 0.06f, 0.09f), dark);
            for (int i = -1; i <= 1; i += 2)
                Part("Eye", PrimitiveType.Sphere, guest.transform, new Vector3(i * 0.065f, headY + 0.025f, younger ? 0.162f : 0.145f),
                    Vector3.one * (younger ? 0.043f : 0.035f), dark);
            leftArm = Part("LeftArm", PrimitiveType.Capsule, guest.transform, new Vector3(-0.31f, 1.03f, 0f), new Vector3(0.13f, 0.31f, 0.13f), skin).transform;
            rightArm = Part("RightArm", PrimitiveType.Capsule, guest.transform, new Vector3(0.31f, 1.03f, 0f), new Vector3(0.13f, 0.31f, 0.13f), skin).transform;
            leftLeg = Part("LeftLeg", PrimitiveType.Capsule, guest.transform, new Vector3(-0.13f, 0.39f, 0f), new Vector3(0.18f, 0.34f, 0.2f), dark).transform;
            rightLeg = Part("RightLeg", PrimitiveType.Capsule, guest.transform, new Vector3(0.13f, 0.39f, 0f), new Vector3(0.18f, 0.34f, 0.2f), dark).transform;
            BoxCollider hit = guest.AddComponent<BoxCollider>(); hit.isTrigger = true;
            hit.center = Vector3.up * 1.05f; hit.size = new Vector3(0.7f, 1.5f, 0.5f); // 조준만 감지하고 플레이어를 밀지 않습니다.
            GameObject label = new GameObject("CustomerCaption"); label.layer = 2; label.transform.SetParent(guest.transform, false);
            label.transform.localPosition = Vector3.up * 2.35f;
            guestCaption = label.AddComponent<TextMesh>(); guestCaption.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            guestCaption.fontSize = 64; guestCaption.characterSize = 0.04f; guestCaption.anchor = TextAnchor.MiddleCenter;
            guestCaption.color = Color.white; guestCaption.GetComponent<Renderer>().sharedMaterial = guestCaption.font.material;
            SetCaption(""); // 응대 전에는 나이나 취한 상태를 문자로 알려주지 않습니다.
            state = State.Arriving;
        }
        private void SetCaption(string caption)
        {
            if (guestCaption == null) return;
            guestCaption.text = caption;
            if (string.IsNullOrEmpty(caption)) return;
            guestCaption.font.RequestCharactersInTexture(caption, 64);
            guestCaption.transform.localScale = Vector3.one;
            Bounds bounds = guestCaption.GetComponent<Renderer>().localBounds;
            if (bounds.size.x > 0f && bounds.size.y > 0f)
                guestCaption.transform.localScale = Vector3.one * Mathf.Min(1.5f / bounds.size.x, 0.15f / bounds.size.y);
        }
        private bool WalkTo(Vector3 target)
        {
            Vector3 delta = target - guest.transform.position;
            if (delta.sqrMagnitude < 0.0025f) { guest.transform.position = target; return true; }
            guest.transform.rotation = Quaternion.RotateTowards(guest.transform.rotation, Quaternion.LookRotation(delta), Time.deltaTime * 240f);
            guest.transform.position = Vector3.MoveTowards(guest.transform.position, target, Time.deltaTime * 1.25f);
            float swing = Mathf.Sin(Time.time * 8f) * 23f;
            leftArm.localRotation = Quaternion.Euler(swing, 0f, 0f); rightArm.localRotation = Quaternion.Euler(-swing, 0f, 0f);
            leftLeg.localRotation = Quaternion.Euler(-swing, 0f, 0f); rightLeg.localRotation = Quaternion.Euler(swing, 0f, 0f);
            return false;
        }
        private bool AimingAtGuest()
        {
            return guest != null && Physics.Raycast(owner.playerCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f)),
                out RaycastHit hit, 4f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Collide)
                && hit.transform.IsChildOf(guest.transform);
        }
        private void OpenDialog()
        {
            dialogLock = Cursor.lockState; dialogCursor = Cursor.visible; dialogOpen = true;
            Cursor.lockState = CursorLockMode.None; Cursor.visible = true;
        }
        private void CloseDialog()
        {
            if (!dialogOpen) return;
            dialogOpen = false; Cursor.lockState = dialogLock; Cursor.visible = dialogCursor;
            owner.practiceReturnFrame = Time.frameCount;
        }
        public void Tick()
        {
            if (disposed) return;
            root.SetActive(true);
            TickNightTransition();
            if (guestCaption != null)
            {
                Vector3 away = guestCaption.transform.position - owner.playerCamera.transform.position;
                if (away.sqrMagnitude > 0.001f) guestCaption.transform.rotation = Quaternion.LookRotation(away);
            }
            if (dialogOpen) { if (owner.PressedRecipeClose()) CloseDialog(); return; }
            if (state == State.Waiting) { if (Time.unscaledTime >= deadline) SpawnGuest(); return; }
            if (state == State.Arriving)
            {
                if (!atAisle) { if (WalkTo(aisle)) atAisle = true; }
                else if (WalkTo(counter))
                {
                    guest.transform.rotation = Quaternion.identity;
                    leftArm.localRotation = rightArm.localRotation = leftLeg.localRotation = rightLeg.localRotation = Quaternion.identity;
                    state = State.Screening;
                    owner.ShowAction("CUSTOMER ARRIVED", "Approach the bar and click the customer to respond.", 3f);
                }
                return;
            }
            if (state == State.Receiving)
            {
                if (order < 2 && Time.unscaledTime >= deadline - 2f)
                    owner.SetVisible(order == 0 ? owner.schoonerGlass : owner.pintGlass, false);
                if (receivedDrink != null)
                    receivedDrink.transform.position = Vector3.Lerp(drinkStart, guest.transform.position + new Vector3(0.31f, 1.21f, 0.23f),
                        Mathf.Clamp01((Time.unscaledTime - (deadline - 2.5f)) / 1.4f));
                if (Time.unscaledTime >= deadline)
                {
                    if (receivedDrink != null) receivedDrink.transform.SetParent(guest.transform, true);
                    atAisle = false; state = State.Leaving;
                }
                return;
            }
            if (state == State.Leaving)
            {
                if (Time.unscaledTime < deadline) return;
                if (!atAisle) { if (WalkTo(aisle)) atAisle = true; }
                else if (WalkTo(entrance))
                {
                    UnityEngine.Object.Destroy(guest); guest = null; guestCaption = null;
                    if (receivedDrink != null) UnityEngine.Object.Destroy(receivedDrink);
                    owner.ResetServiceGlasses(); order = -1; state = State.Waiting;
                    deadline = Time.unscaledTime + Random.Range(6f, 11f);
                }
                return;
            }
            if (owner.practiceReturnFrame == Time.frameCount || Cursor.lockState != CursorLockMode.Locked) return;
            if (state == State.Screening)
            {
                if (AimingAtGuest())
                {
                    owner.prompt = "LEFT CLICK - Talk to customer";
                    if (owner.PressedLeftClick()) OpenDialog();
                }
                return;
            }
            if (HasCocktailOrder)
            {
                if (owner.IsNearCocktailStation())
                {
                    owner.prompt = "LEFT CLICK - Make " + orderNames[order] + " / 45 seconds / ONE attempt";
                    if (owner.PressedLeftClick())
                    {
                        if (owner.practice != null) owner.practice.Dispose();
                        owner.practice = new CocktailPractice(owner, order - 2, true);
                    }
                }
                return;
            }
            if (!HasBeerOrder) return;
            if (owner.serviceMarker != null) owner.serviceMarker.SetActive(true);
            if (owner.pouring) { owner.prompt = "Pouring beer..."; return; }
            if (owner.heldGlass == null) { owner.CheckGlassPickup(); return; }
            if (owner.IsAimingAtServiceMarker())
            {
                int index = owner.HeldGlassIndex();
                owner.prompt = owner.filled[index] ? "LEFT CLICK - Serve " + orderNames[order] : "Fill the glass at the beer tap first.";
                if (owner.PressedLeftClick() && owner.filled[index]) owner.ServeGlass(index);
                return;
            }
            owner.CheckPouring();
            if (owner.PressedLeftClick() && !owner.pouring) owner.DropGlass();
        }
        private void AcceptOrder()
        {
            if (state != State.Screening) return;
            if (kind != GuestKind.Regular)
            {
                DecisionError(kind == GuestKind.CheckID ? "This customer is under 18. Verify age and refuse alcohol service."
                    : "This customer is intoxicated. Alcohol service should be refused.");
                return;
            }
            CloseDialog(); state = State.Preparing;
            SetCaption(orderNames[order]);
            owner.ShowAction("ORDER TAKEN", orderNames[order] + (order < 2 ? " - Fill and serve on the glowing marker." : " - Walk to the cocktail table."), 3f);
        }
        private void RefuseService(bool ageReason)
        {
            if (state != State.Screening) return;
            if (ageReason && !idChecked) { idChecked = true; return; }
            bool correctReason = ageReason ? kind == GuestKind.CheckID : kind == GuestKind.Intoxicated;
            if (!correctReason)
            {
                DecisionError(ageReason ? "The ID confirms legal age. Age is not a valid refusal reason for this customer."
                    : "Intoxication was not the correct refusal reason for this customer.");
                return;
            }
            CloseDialog(); refusedCount++; order = -1; state = State.Leaving; atAisle = false;
            deadline = Time.unscaledTime + 2f;
            SetCaption("SERVICE REFUSED");
            owner.ShowAction("SALE REFUSED", ageReason ? "ID checked: under 18. No alcohol served."
                : "Customer is intoxicated. No alcohol served.", 4f);
        }
        private void DecisionError(string reason)
        {
            if (state != State.Screening) return;
            CloseDialog(); missedCount++; order = -1; state = State.Leaving; atAisle = false;
            deadline = Time.unscaledTime + 2f;
            SetCaption("SERVICE DECISION FAILED");
            if (owner.sounds != null) owner.sounds.PlayResult(false);
            owner.ShowAction("SERVICE DECISION FAILED", reason, 4f);
        }
        public void CompleteCocktail(bool success)
        {
            if (disposed || !HasCocktailOrder) return;
            CompleteOrder(success);
        }
        public void CompleteBeer()
        {
            if (!disposed && HasBeerOrder) CompleteOrder(true);
        }
        private void CompleteOrder(bool success)
        {
            if (state != State.Preparing) return;
            if (owner.serviceMarker != null) owner.serviceMarker.SetActive(false);
            if (success)
            {
                servedCount++; state = State.Receiving; deadline = Time.unscaledTime + 2.5f;
                SetCaption("THANK YOU!");
                owner.ShowAction("ORDER SERVED", orderNames[order] + " delivered. The next customer arrives shortly.", 4f);
                receivedDrink = new GameObject("CustomerDrink"); receivedDrink.transform.SetParent(root.transform, false);
                drinkStart = owner.serviceMarker.transform.position + Vector3.up * 0.13f;
                receivedDrink.transform.position = drinkStart;
                float height = order == 1 || order == 4 ? 0.27f : 0.20f;
                float diameter = order == 4 ? 0.10f : 0.13f;
                drinkMaterial.color = order == 3 ? new Color(0.75f, 0.15f, 0.08f) : order == 4
                    ? new Color(0.45f, 0.22f, 0.07f) : order == 2 ? new Color(0.65f, 0.92f, 0.75f) : new Color(1f, 0.65f, 0.13f);
                Part("Glass", PrimitiveType.Cylinder, receivedDrink.transform, Vector3.zero, new Vector3(diameter, height * 0.5f, diameter), paper);
                Part("Drink", PrimitiveType.Cylinder, receivedDrink.transform, Vector3.up * (height * 0.5f + 0.005f), new Vector3(diameter * 0.88f, 0.008f, diameter * 0.88f), drinkMaterial);
                // 맥주잔은 서빙 위치에 0.5초 동안 남긴 뒤 손님에게 시각적으로 인계합니다.
            }
            else
            {
                missedCount++; state = State.Leaving; atAisle = false; deadline = Time.unscaledTime + 2f;
                SetCaption("ORDER CANCELLED");
                owner.ShowAction("ORDER FAILED", "This was your only attempt. No drink served. Wait for the next customer.", 4f);
            }
        }
        public void Suspend() { CloseDialog(); if (root != null) root.SetActive(false); }
        private void EnsureStyles()
        {
            if (bodyStyle != null) return;
            bodyStyle = new GUIStyle(GUI.skin.label) { fontSize = 20, wordWrap = true, padding = new RectOffset(0, 0, 0, 0) };
            bodyStyle.normal.textColor = new Color(0.89f, 0.96f, 0.93f);
            titleStyle = new GUIStyle(bodyStyle) { fontSize = 27, fontStyle = FontStyle.Bold };
            smallStyle = new GUIStyle(bodyStyle) { fontSize = 16 };
            buttonStyle = new GUIStyle(GUI.skin.button) { fontSize = 21, fontStyle = FontStyle.Bold, wordWrap = true };
        }
        private static void Panel(Rect rect, Color color)
        {
            Color old = GUI.color; GUI.color = color; GUI.DrawTexture(rect, Texture2D.whiteTexture); GUI.color = old;
        }
        public void DrawTicket(Rect area)
        {
            if (state != State.Preparing || order < 0) return;
            EnsureStyles();
            Panel(area, new Color(0.025f, 0.09f, 0.095f, 0.97f));
            Panel(new Rect(area.x, area.y, 5f, area.height), new Color(0.5f, 0.9f, 0.65f));
            GUI.Label(new Rect(area.x + 16f, area.y + 12f, area.width - 32f, 25f), "ORDER #" + guestNumber.ToString("00"), smallStyle);
            GUI.Label(new Rect(area.x + 16f, area.y + 46f, area.width - 32f, 80f), orderNames[order], titleStyle);
            GUI.Label(new Rect(area.x + 16f, area.y + 140f, area.width - 32f, area.height - 150f), order < 2
                ? "Pick up the correct glass.\nE at the tap to pour.\nLEFT CLICK the glowing serving spot."
                : "Cocktail table\n45 seconds / ONE attempt\nMake the ordered drink, then press SERVE.", smallStyle);
        }
        public void Draw()
        {
            EnsureStyles();
            float scale = Mathf.Min(Screen.width / 1280f, Screen.height / 720f);
            Matrix4x4 saved = GUI.matrix; GUI.matrix = Matrix4x4.TRS(Vector3.zero, Quaternion.identity, Vector3.one * scale);
            float width = Screen.width / scale, height = Screen.height / scale;
            try
            {
                Panel(new Rect(width - 338f, 16f, 322f, 105f), new Color(0.025f, 0.06f, 0.1f, 0.94f));
                GUI.Label(new Rect(width - 320f, 27f, 290f, 34f), "NIGHT SERVICE / OPEN", titleStyle);
                GUI.Label(new Rect(width - 320f, 70f, 290f, 45f), "Served " + servedCount + "   Refused " + refusedCount + "   Missed " + missedCount, smallStyle);
                DrawTicket(new Rect(16f, 24f, 272f, 292f));
                string message = state == State.Waiting ? "The bar is open. Customers arrive every few seconds."
                    : state == State.Arriving ? "A customer is approaching the counter."
                    : state == State.Screening ? "Observe the customer, then click to choose a service decision."
                    : HasCocktailOrder ? "Take the order to the rear cocktail table."
                    : HasBeerOrder ? "Pick up > Pour with E > Serve with LEFT CLICK"
                    : state == State.Receiving ? "The customer is receiving the drink." : "Customer leaving. Next arrival shortly.";
                if (Time.unscaledTime >= owner.actionUntil)
                {
                    Panel(new Rect((width - 660f) * 0.5f, height - 82f, 660f, 62f), new Color(0.025f, 0.06f, 0.1f, 0.94f));
                    GUI.Label(new Rect((width - 624f) * 0.5f, height - 68f, 624f, 48f), message, bodyStyle);
                }
                if (HasBeerOrder && owner.serviceMarker != null)
                {
                    Vector3 screen = owner.playerCamera.WorldToScreenPoint(owner.serviceMarker.transform.position + Vector3.up * 0.36f);
                    if (screen.z > 0f)
                    {
                        Rect tag = new Rect(Mathf.Clamp(screen.x / scale - 120f, 296f, width - 256f), Mathf.Clamp((Screen.height - screen.y) / scale, 150f, height - 160f), 240f, 68f);
                        Panel(tag, new Color(0.02f, 0.17f, 0.16f, 0.94f)); GUI.Label(tag, "SERVE HERE\nLEFT CLICK", bodyStyle);
                    }
                }
                if (!dialogOpen) return;
                Panel(new Rect(0f, 0f, width, height), new Color(0f, 0f, 0f, 0.78f));
                Rect modal = new Rect((width - 740f) * 0.5f, (height - 400f) * 0.5f, 740f, 400f);
                Panel(modal, new Color(0.025f, 0.075f, 0.10f, 1f));
                GUI.Label(new Rect(modal.x + 28f, modal.y + 25f, 684f, 45f), "CUSTOMER / SERVICE DECISION", titleStyle);
                string detail = "I'd like a " + orderNames[order] + ", please.";
                if (idChecked) detail += kind == GuestKind.CheckID ? "\n\nID RESULT: UNDER 18" : "\n\nID RESULT: 18 OR OVER";
                GUI.Label(new Rect(modal.x + 28f, modal.y + 92f, 684f, 115f), detail, bodyStyle);
                float buttonY = modal.y + 226f;
                if (GUI.Button(new Rect(modal.x + 28f, buttonY, 216f, 78f), "SELL / TAKE ORDER", buttonStyle)) { AcceptOrder(); return; }
                if (GUI.Button(new Rect(modal.x + 262f, buttonY, 216f, 78f), idChecked ? "REFUSE / ID & AGE" : "ASK ID / AGE CHECK", buttonStyle)) { RefuseService(true); return; }
                if (GUI.Button(new Rect(modal.x + 496f, buttonY, 216f, 78f), "REFUSE / INTOXICATION", buttonStyle)) { RefuseService(false); return; }
                if (GUI.Button(new Rect(modal.x + 28f, modal.yMax - 68f, 684f, 44f), "CLOSE [ESC]", buttonStyle)) CloseDialog();
            }
            finally { GUI.matrix = saved; }
        }
        public void Dispose()
        {
            if (disposed) return; disposed = true; CloseDialog();
            if (root != null) UnityEngine.Object.Destroy(root);
            foreach (Material material in materials) if (material != null) UnityEngine.Object.Destroy(material);
            for (int i = 0; i < dimmedLights.Count; i++) if (dimmedLights[i] != null)
            { dimmedLights[i].intensity = lightIntensities[i]; dimmedLights[i].color = lightColors[i]; }
            RenderSettings.ambientMode = savedAmbientMode; RenderSettings.ambientLight = savedAmbient;
            RenderSettings.ambientSkyColor = savedSkyColor; RenderSettings.ambientEquatorColor = savedEquatorColor; RenderSettings.ambientGroundColor = savedGroundColor;
            RenderSettings.skybox = savedGlobalSkybox;
            if (cameraSkybox != null) cameraSkybox.material = savedCameraSkybox;
            if (nightSkybox != null) UnityEngine.Object.Destroy(nightSkybox);
            RenderSettings.ambientIntensity = savedAmbientIntensity; RenderSettings.reflectionIntensity = savedReflection;
            RenderSettings.fog = savedFog; RenderSettings.fogMode = savedFogMode; RenderSettings.fogColor = savedFogColor; RenderSettings.fogDensity = savedFogDensity;
            if (owner.playerCamera != null) { owner.playerCamera.clearFlags = savedClearFlags; owner.playerCamera.backgroundColor = savedBackground; }
        }
    }

    private sealed class GlassHome
    {
        private readonly GameObject glass;
        private readonly Transform parent;
        private readonly Vector3 position, scale;
        private readonly Quaternion rotation;
        private readonly Collider[] colliders;
        private readonly bool[] colliderStates;
        public GlassHome(GameObject glass)
        {
            this.glass = glass; if (glass == null) return;
            parent = glass.transform.parent; position = glass.transform.localPosition; rotation = glass.transform.localRotation; scale = glass.transform.localScale;
            colliders = glass.GetComponentsInChildren<Collider>(true); colliderStates = new bool[colliders.Length];
            for (int i = 0; i < colliders.Length; i++) colliderStates[i] = colliders[i].enabled;
        }
        public void Restore()
        {
            if (glass == null) return;
            glass.transform.SetParent(parent, false); glass.transform.localPosition = position; glass.transform.localRotation = rotation; glass.transform.localScale = scale;
            for (int i = 0; i < colliders.Length; i++) if (colliders[i] != null) colliders[i].enabled = colliderStates[i];
            foreach (Renderer renderer in glass.GetComponentsInChildren<Renderer>()) renderer.enabled = true;
        }
    }

    private void ResetServiceGlasses()
    {
        if (heldGlass != null) DropGlass();
        for (int index = 0; index < 2; index++)
        {
            if (filledVisuals[index] != null) { filledVisuals[index].SetActive(false); Destroy(filledVisuals[index]); filledVisuals[index] = null; }
            filled[index] = false;
            if (glassHomes[index] != null) glassHomes[index].Restore();
            if (serviceRings[index] != null) serviceRings[index].sharedMaterial = markerMaterial;
        }
    }

