        private void ResetRound()
        {
            if (owner.sounds != null) owner.sounds.StopAll();
            StopPour(false);
            foreach (GameObject effect in iceEffects) if (effect != null) UnityEngine.Object.Destroy(effect);
            iceEffects.Clear();
            for (int index = 0; index < fills.Length; index++) { levels[index] = 0f; fills[index].SetActive(false); }
            foreach (GameObject ring in rings) ring.SetActive(false);
            ReturnTool();
            shakerLid.SetActive(false);
            phase = Phase.ChooseGlass; selectedGlass = -1;
            System.Array.Clear(ingredientTotals, 0, ingredientTotals.Length);
            System.Array.Clear(included, 0, included.Length);
            shakerIced = false; glassIced = false; stirred = false; shaken = false; transferred = false;
            noticeUntil = 0f; noticeStarted = 0f; noticeCelebrate = false;
            pendingPourTitle = ""; pendingPourDetail = "";
            strokes = 0; travel = 0f; travelDirection = 0; lastStrokeDirection = 0;
            failed = false; completed = false; error = ""; remaining = RoundSeconds;
            awaitingStart = !serviceOrder; roundRecorded = false;
            measure = 1f;
            jigger.transform.localPosition = jiggerHome;
            jigger.transform.localRotation = Quaternion.identity;
            UpdateJiggerReadout();
            hovered = -1;
        }

        private float RequiredAmount(int ingredient)
        {
            int index = System.Array.IndexOf(recipeIngredients[recipe], ingredient);
            return index < 0 ? -1f : recipeAmounts[recipe][index];
        }

        private bool NeedsIngredient(int ingredient)
        {
            float required = RequiredAmount(ingredient);
            if (required < 0f) return false;
            if (ingredient == 6 && recipe == 2) return !shakerIced || !glassIced;
            return required > 0f ? ingredientTotals[ingredient] < required - 0.001f : !included[ingredient];
        }

        private bool AllIngredientsReady()
        {
            foreach (int ingredient in recipeIngredients[recipe])
                if (NeedsIngredient(ingredient)) return false;
            return true;
        }

        private bool ShakerReady()
        {
            return shakerIced && ingredientTotals[0] >= 0.499f && ingredientTotals[1] >= 0.499f
                && ingredientTotals[2] >= 0.499f && ingredientTotals[3] >= 0.499f;
        }

        private void RefreshPhase()
        {
            if (selectedGlass < 0) { phase = Phase.ChooseGlass; return; }
            if (recipe == 0) phase = AllIngredientsReady() ? Phase.Ready : Phase.Build;
            else if (recipe == 1) phase = !AllIngredientsReady() ? Phase.Build : stirred ? Phase.Ready : Phase.Stir;
            else
            {
                if (!ShakerReady()) phase = Phase.Build;
                else if (!shaken) phase = Phase.Shake;
                else if (!glassIced) phase = Phase.GlassIce;
                else if (!transferred) phase = Phase.Transfer;
                else phase = AllIngredientsReady() ? Phase.Ready : Phase.TopUp;
                shakerLid.SetActive(ShakerReady() && !transferred);
            }
        }

        private string NextInstruction()
        {
            switch (phase)
            {
                case Phase.ChooseGlass: return "Choose the " + glassNames[recipe] + ".";
                case Phase.Stir: return toolHeld ? "Stir for 15 full left / right round trips." : "Ingredients complete. Click the stirring stick.";
                case Phase.Shake: return toolHeld ? "Shake for 15 full up / down round trips." : "Shaker ready. Click it to start shaking.";
                case Phase.GlassIce: return "Click Ice to add ice to your serving glass.";
                case Phase.Transfer: return "Click the shaker to pour into the iced long-drink glass.";
                case Phase.Ready: return serviceOrder ? "Your cocktail is ready. Click SERVE." : "Your cocktail is ready. Click FINISH.";
                default: return "Add ingredients in ANY ORDER. Match the totals below.";
            }
        }

        private void Fail(string message)
        {
            if (failed || completed) return;
            noticeUntil = 0f;
            error = serviceOrder || trial == 0 ? message : message.StartsWith("Time's up")
                ? "Time's up! The " + RoundSeconds.ToString("0") + "-second limit has expired."
                : "The glass, ingredients, amounts or technique are not correct. Please try again.";
            failed = true; StopPour(false); ReturnTool();
            if (owner.sounds != null) owner.sounds.PlayResult(false);
        }

        private void AddIngredient(int ingredient)
        {
            if (selectedGlass < 0) { Fail("Choose the correct glass before adding ingredients."); return; }
            float required = RequiredAmount(ingredient);
            if (required < 0f)
            {
                Fail("Incorrect ingredient.\n" + ingredientNames[ingredient] + " is not used in " + recipeNames[recipe] + "."); return;
            }
            if (required == 0f && !NeedsIngredient(ingredient))
            {
                Notify("ALREADY ADDED", ingredientNames[ingredient] + " is already in the drink. Nothing extra was added.", 2f, false);
                return;
            }
            if (required > 0f && ingredientTotals[ingredient] + measure > required + 0.001f)
            {
                Fail("Too much " + ingredientNames[ingredient] + ".\nRequired total: " + required.ToString("0.#")
                    + " oz. Already added: " + ingredientTotals[ingredient].ToString("0.#") + " oz."); return;
            }
            if (ingredient == 6)
            {
                bool intoShaker = recipe == 2 && !shakerIced;
                if (intoShaker) { AddIce(shaker); shakerIced = true; }
                else { AddIce(glassObjects[selectedGlass]); glassIced = true; }
                Notify("ICE ADDED", intoShaker ? "Ice is in the shaker." : "Ice is in your serving glass.", celebrate: true);
            }
            else
            {
                GameObject vessel = recipe == 2 && ingredient >= 0 && ingredient <= 3 ? shaker : glassObjects[selectedGlass];
                float boost = required > 0f ? 0.028f * measure / required : 0.07f;
                string result = required > 0f ? measure.ToString("0.#") + " oz added. Total: "
                    + (ingredientTotals[ingredient] + measure).ToString("0.#") + " / " + required.ToString("0.#") + " oz." : "Top-up complete.";
                BeginPour(targets[10 + ingredient], vessel, ingredientMaterials[ingredient], boost,
                    ingredientNames[ingredient].ToUpperInvariant() + " ADDED", result);
                if (required > 0f) ingredientTotals[ingredient] += measure;
            }
            included[ingredient] = true;
            RefreshPhase();
        }

        private void AddIce(GameObject vessel)
        {
            for (int index = 0; index < 4; index++)
            {
                GameObject cube = Part("AddedIce", PrimitiveType.Cube, vessel.transform,
                    new Vector3((index % 2 - 0.5f) * 0.04f, 0.06f + index / 2 * 0.035f, (index / 2 - 0.5f) * 0.035f), Vector3.one * 0.033f, ice);
                cube.transform.localRotation = Quaternion.Euler(12f * index, 23f * index, 9f * index);
                iceEffects.Add(cube);
            }
            if (owner.sounds != null) owner.sounds.PlayIce();
        }

        private void BeginPour(GameObject bottle, GameObject vessel, Material material, float boost,
            string completionTitle, string completionDetail)
        {
            pendingPourTitle = completionTitle; pendingPourDetail = completionDetail;
            pouring = true; pourTime = 0f; pourObject = bottle; pourTarget = vessel; pourBoost = boost;
            pourStartPosition = bottle.transform.localPosition; pourStartRotation = bottle.transform.localRotation;
            stream.GetComponent<Renderer>().sharedMaterial = material;
            if (owner.sounds != null) owner.sounds.PlayContinuous(ActionSound.DrinkPour);
        }

        private void TickPour()
        {
            if (owner.sounds != null) owner.sounds.PlayContinuous(ActionSound.DrinkPour);
            pourTime += Time.unscaledDeltaTime;
            float time = Mathf.Clamp01(pourTime / 0.45f);
            float blend = time < 0.25f ? time * 4f : time > 0.75f ? (1f - time) * 4f : 1f;
            Quaternion tilted = Quaternion.Euler(0f, 0f, -55f);
            Vector3 spout = tilted * (Vector3.up * (pourObject == shaker ? 0.3f : 0.42f));
            Vector3 destination = pourTarget.transform.localPosition + Vector3.up * 0.35f - spout;
            pourObject.transform.localPosition = Vector3.Lerp(pourStartPosition, destination, blend);
            pourObject.transform.localRotation = Quaternion.Slerp(pourStartRotation, tilted, blend);
            stream.transform.localPosition = pourTarget.transform.localPosition + Vector3.up * 0.22f;
            stream.SetActive(time > 0.25f && time < 0.75f);
            if (time >= 1f) StopPour(true);
        }

        private void StopPour(bool apply)
        {
            if (!pouring) return;
            if (owner.sounds != null) owner.sounds.StopContinuous();
            if (pourObject != null) { pourObject.transform.localPosition = pourStartPosition; pourObject.transform.localRotation = pourStartRotation; }
            if (stream != null) stream.SetActive(false);
            if (apply && pourTarget != null)
            {
                int index = pourTarget == shaker ? 3 : selectedGlass;
                float cap = index == 3 ? 0.20f : glassHeights[index] * 0.73f;
                levels[index] = Mathf.Min(cap, levels[index] + pourBoost);
                GameObject fill = fills[index];
                fill.SetActive(true);
                fill.transform.localPosition = Vector3.up * (0.008f + levels[index] * 0.5f);
                Vector3 scale = fill.transform.localScale; scale.y = levels[index] * 0.5f; fill.transform.localScale = scale;
            }
            if (apply && pourObject == shaker) { fills[3].SetActive(false); levels[3] = 0f; }
            pouring = false; pourObject = null; pourTarget = null;
            if (apply) Notify(pendingPourTitle, pendingPourDetail, celebrate: true);
            pendingPourTitle = ""; pendingPourDetail = "";
        }

        private void SelectTarget(int code)
        {
            if (code >= 10 && code < 20) { AddIngredient(code - 10); return; }
            if (code >= 0 && code < 3)
            {
                if (phase != Phase.ChooseGlass) return;
                if (code != recipe) { Fail("Incorrect glass.\nChoose the " + glassNames[recipe] + " for " + recipeNames[recipe] + "."); return; }
                selectedGlass = code; rings[code].SetActive(trial < 2); phase = Phase.Build;
                Notify("CORRECT GLASS", glassNames[code] + " selected. Add your ingredients.", celebrate: true); return;
            }
            if (code == 32 || code == 33) { SetMeasure(code == 32 ? 1f : 0.5f); return; }
            if (phase == Phase.Transfer && code == 31)
            {
                shakerLid.SetActive(false);
                BeginPour(shaker, glassObjects[selectedGlass], liquid, 0.15f,
                    "POUR COMPLETE", "The shaker mixture is now in your serving glass.");
                transferred = true; RefreshPhase(); return;
            }
            if ((phase == Phase.Stir && code == 30) || (phase == Phase.Shake && code == 31))
            {
                toolHeld = true; toolPickedFrame = Time.frameCount; travel = 0f; travelDirection = 0; toolOffset = 0f;
                Notify(phase == Phase.Stir ? "STIRRING STICK PICKED UP" : "SHAKER PICKED UP",
                    phase == Phase.Stir ? "Hold LEFT CLICK and move left / right." : "Hold LEFT CLICK and move up / down.", 2f);
                if (phase == Phase.Stir)
                    stirrer.transform.position = glassObjects[selectedGlass].transform.position + Vector3.up * 0.015f;
                else
                {
                    shaker.transform.localPosition = new Vector3(0.3f, 1.28f, -0.72f);
                    shaker.transform.localRotation = Quaternion.Euler(0f, 0f, -15f);
                }
            }
        }

        private void ReturnTool()
        {
            if (owner.sounds != null) owner.sounds.StopContinuous();
            toolHeld = false; toolOffset = 0f;
            if (stirrer != null) { stirrer.transform.localPosition = stirStart; stirrer.transform.localRotation = Quaternion.identity; }
            if (shaker != null) { shaker.transform.localPosition = shakerStart; shaker.transform.localRotation = Quaternion.identity; }
        }

        private void CountMotion(float delta)
        {
            if (Mathf.Abs(delta) < 0.5f) return;
            int direction = delta > 0f ? 1 : -1;
            if (direction != travelDirection) { travelDirection = direction; travel = 0f; }
            travel += Mathf.Abs(delta);
            float threshold = Mathf.Clamp(Screen.height * 0.05f, 20f, 60f);
            if (travel < threshold || direction == lastStrokeDirection) return;
            lastStrokeDirection = direction; travel = 0f; strokes++;
            if (strokes >= 30)
            {
                bool wasStirring = phase == Phase.Stir;
                ReturnTool();
                if (wasStirring) stirred = true; else shaken = true;
                RefreshPhase();
                Notify(wasStirring ? "STIRRING COMPLETE" : "SHAKING COMPLETE", "15 / 15 round trips. " + NextInstruction(), 3f, celebrate: true);
            }
        }

        private Vector2 Pointer()
        {
#if ENABLE_INPUT_SYSTEM
            return Mouse.current != null ? Mouse.current.position.ReadValue() : Vector2.zero;
#else
            return Input.mousePosition;
#endif
        }
        private Vector2 PointerDelta()
        {
#if ENABLE_INPUT_SYSTEM
            return Mouse.current != null ? Mouse.current.delta.ReadValue() : Vector2.zero;
#else
            return new Vector2(Input.GetAxis("Mouse X"), Input.GetAxis("Mouse Y")) * 18f;
#endif
        }
        private bool LeftHeld()
        {
#if ENABLE_INPUT_SYSTEM
            return Mouse.current != null && Mouse.current.leftButton.isPressed;
#else
            return Input.GetMouseButton(0);
#endif
        }
        private Rect MeasurePanel() { return new Rect(16f, Screen.height - 118f, 302f, 102f); }
        private Rect FinishButton() { return new Rect(Screen.width - 202f, Screen.height - 83f, 186f, 62f); }
        private bool OverUI(Vector2 pointer)
        {
            if (serviceOrder) return ServiceTicketRect().Contains(pointer)
                || new Rect(ServiceTicketRect().xMax + 16f, 0f, Screen.width, 132f).Contains(pointer)
                || MeasurePanel().Contains(pointer) || FinishButton().Contains(pointer);
            if (trial == 2) return TimerOnlyRect().Contains(pointer);
            return new Rect(0f, 0f, Screen.width, 132f).Contains(pointer) || MeasurePanel().Contains(pointer)
                || ((phase == Phase.Ready || trial == 1) && FinishButton().Contains(pointer));
        }
        private Rect LabelRect(int code)
        {
            if (code >= 10 && code < 20)
            {
                int index = code - 10;
                float left = serviceOrder ? ServiceTicketRect().xMax + 16f : 16f;
                float cellWidth = (Screen.width - left - 16f) / 5f;
                return new Rect(left + index % 5 * cellWidth, 136f + index / 5 * 54f, cellWidth - 6f, 48f);
            }
            GameObject target = targets[code];
            float height = code >= 10 && code < 20 ? (code == 16 ? 0.17f : 0.49f) : -0.03f;
            Vector3 screen = camera.WorldToScreenPoint(target.transform.position + Vector3.up * height);
            const float labelWidth = 136f;
            float x = Mathf.Clamp(screen.x - labelWidth * 0.5f, 8f, Mathf.Max(8f, Screen.width - labelWidth - 8f));
            return new Rect(x, Screen.height - screen.y - 21f, labelWidth, 42f);
        }
        private string TargetName(int code)
        {
            if (code < 3) return glassNames[code];
            if (code < 20)
            {
                int ingredient = code - 10;
                return (code - 9).ToString("00") + "  " + ingredientNames[ingredient] + "\n" + IngredientProgress(ingredient);
            }
            if (code == 30) return trial == 0 && phase == Phase.Stir && !toolHeld ? "STIRRING STICK\nCLICK TO PICK UP" : "Stirring stick";
            if (code == 32) return "Jigger: 1 oz";
            if (code == 33) return "Jigger: 0.5 oz";
            return "Shaker";
        }
        public void Tick()
        {
            if (!IsActive) return;
            if (owner.PressedRecipeClose()) { Exit(); return; }
            if (awaitingStart || failed || completed)
            {
                if (owner.sounds != null) owner.sounds.StopContinuous();
                return;
            }
            remaining = Mathf.Max(0f, remaining - Time.unscaledDeltaTime);
            if (remaining <= 0f) { Fail("Time's up!\nThe " + RoundSeconds.ToString("0") + "-second limit has expired."); return; }
            if (FinishRequested()) { TryFinish(); return; }
            if (!pouring && !toolHeld && MeasureSwitchRequested()) SetMeasure(measure == 1f ? 0.5f : 1f);
            if (pouring) { TickPour(); return; }
            Vector2 pointer = Pointer(); Vector2 guiPointer = new Vector2(pointer.x, Screen.height - pointer.y);
            if (toolHeld)
            {
                if (LeftHeld() && !OverUI(guiPointer) && toolPickedFrame != Time.frameCount)
                {
                    Vector2 delta = PointerDelta();
                    float actionDelta = phase == Phase.Stir ? delta.x : delta.y;
                    if (owner.sounds != null)
                    {
                        if (Mathf.Abs(actionDelta) >= 0.5f)
                            owner.sounds.PlayContinuous(phase == Phase.Stir ? ActionSound.Stir : ActionSound.Shake);
                        else owner.sounds.PauseContinuous();
                    }
                    toolOffset = Mathf.Clamp(toolOffset + (phase == Phase.Stir ? delta.x : delta.y) * 0.002f, -0.12f, 0.12f);
                    if (phase == Phase.Stir)
                        stirrer.transform.position = glassObjects[selectedGlass].transform.position + new Vector3(toolOffset * 0.35f, 0.015f, 0f);
                    else
                    {
                        shaker.transform.localPosition = new Vector3(0.3f, 1.28f + toolOffset, -0.72f);
                        shaker.transform.localRotation = Quaternion.Euler(0f, 0f, -15f);
                    }
                    CountMotion(phase == Phase.Stir ? delta.x : delta.y);
                }
                else
                {
                    if (owner.sounds != null) owner.sounds.PauseContinuous();
                    travel = 0f; travelDirection = 0;
                }
                return;
            }
            if (owner.sounds != null) owner.sounds.StopContinuous();
            hovered = -1;
            if (OverUI(guiPointer)) return;
            foreach (int code in targets.Keys)
                if (ShowTargetLabel(code) && LabelRect(code).Contains(guiPointer)) { hovered = code; break; }
            if (hovered < 0 && Physics.Raycast(camera.ScreenPointToRay(pointer), out RaycastHit hit, 8f,
                1 << Layer, QueryTriggerInteraction.Ignore) && hitTargets.TryGetValue(hit.collider, out int found)) hovered = found;
            if (hovered >= 0 && owner.PressedLeftClick()) SelectTarget(hovered);
        }

        private bool FinishRequested()
        {
#if ENABLE_INPUT_SYSTEM
            return Keyboard.current != null && (Keyboard.current.enterKey.wasPressedThisFrame || Keyboard.current.numpadEnterKey.wasPressedThisFrame);
#else
            return Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter);
#endif
        }
        private bool MeasureSwitchRequested()
        {
#if ENABLE_INPUT_SYSTEM
            return Keyboard.current != null && Keyboard.current.rKey.wasPressedThisFrame;
#else
            return Input.GetKeyDown(KeyCode.R);
#endif
        }
        private void SetMeasure(float value)
        {
            measure = value;
            jigger.transform.localPosition = jiggerHome + (value == 0.5f ? Vector3.up * 0.115f : Vector3.zero);
            jigger.transform.localRotation = value == 0.5f ? Quaternion.Euler(180f, 0f, 0f) : Quaternion.identity;
            UpdateJiggerReadout();
            Notify("MEASURE SET", "The jigger is set to " + value.ToString("0.#") + " oz.", 1.6f);
        }
        private void UpdateJiggerReadout()
        {
            if (jiggerReadout == null) return;
            string content = measure.ToString("0.#") + " oz";
            labelFont.RequestCharactersInTexture(content, 64, FontStyle.Bold);
            jiggerReadout.text = content;
            jiggerReadout.transform.localScale = Vector3.one;
            Bounds bounds = jiggerReadout.GetComponent<Renderer>().localBounds;
            if (bounds.size.x > 0f && bounds.size.y > 0f)
                jiggerReadout.transform.localScale = Vector3.one * Mathf.Min(0.117f / bounds.size.x, 0.0396f / bounds.size.y);
        }
        private void TryFinish()
        {
            if (awaitingStart || failed || completed || pouring) return;
            if (phase != Phase.Ready)
            {
                Fail(trial == 0 ? "The drink is not complete.\n" + NextInstruction() : "The drink is not complete.");
                return;
            }
            completed = true;
            if (owner.sounds != null) owner.sounds.PlayResult(true);
            if (serviceOrder) { Exit(); return; }
            if (!roundRecorded)
            {
                owner.passedTrials[recipe] = Mathf.Max(owner.passedTrials[recipe], trial + 1);
                roundRecorded = true;
            }
        }
        private Rect TimerOnlyRect() { return new Rect(Screen.width - 170f, 16f, 154f, 54f); }

        private void Notify(string title, string detail, float duration = 2.4f, bool success = true, bool celebrate = false)
        {
            if (trial == 2) return;
            noticeTitle = title; noticeDetail = trial == 0 ? detail : "Action complete.";
            noticeStarted = Time.unscaledTime; noticeUntil = noticeStarted + duration;
            noticeSuccess = success; noticeCelebrate = celebrate && success;
        }
        private bool ShowTargetLabel(int code)
        {
            if (serviceOrder) return (code >= 10 && code < 20) || (code < 3 && phase == Phase.ChooseGlass)
                || hovered == code || (code == 30 && phase == Phase.Stir) || (code == 31 && (phase == Phase.Shake || phase == Phase.Transfer));
            if (trial == 2) return false;
            if (trial == 1) return (code >= 10 && code < 20) || (code < 3 && phase == Phase.ChooseGlass) || hovered == code;
            if (code >= 10 && code < 20) return true;
            if (toolHeld) return false;
            if (code < 3) return phase == Phase.ChooseGlass || hovered == code;
            return hovered == code || (code == 30 && phase == Phase.Stir)
                || (code == 31 && (phase == Phase.Shake || phase == Phase.Transfer));
        }
        private string IngredientProgress(int ingredient)
        {
            float required = RequiredAmount(ingredient);
            if (required < 0f) return "Not in recipe";
            if (trial > 0) return included[ingredient] ? "Added" : "Recipe ingredient";
            if (required > 0f) return ingredientTotals[ingredient].ToString("0.#") + " / " + required.ToString("0.#") + " oz";
            if (ingredient == 6 && recipe == 2) return ((shakerIced ? 1 : 0) + (glassIced ? 1 : 0)) + " / 2 vessels";
            return included[ingredient] ? "ADDED" : ingredient == 6 ? "Add ice" : "Top up";
        }
        private int CompletedIngredientCount()
        {
            int count = 0;
            foreach (int ingredient in recipeIngredients[recipe]) if (!NeedsIngredient(ingredient)) count++;
            return count;
        }
        private string StageLabel()
        {
            switch (phase)
            {
                case Phase.ChooseGlass: return "SELECT YOUR GLASS";
                case Phase.Stir: return "STIR THE COCKTAIL";
                case Phase.Shake: return "SHAKE THE MIXTURE";
                case Phase.GlassIce: return "ADD SERVING ICE";
                case Phase.Transfer: return "POUR INTO THE GLASS";
                case Phase.TopUp: return "FINAL INGREDIENTS";
                case Phase.Ready: return "READY TO FINISH";
                default: return "ADD YOUR INGREDIENTS";
            }
        }
        private void EnsureStyles()
        {
            if (bodyStyle != null) return;
            bodyStyle = new GUIStyle(GUI.skin.label) { fontSize = 19, wordWrap = true, alignment = TextAnchor.MiddleLeft, padding = new RectOffset(0, 0, 0, 0) };
            bodyStyle.normal.textColor = ink;
            titleStyle = new GUIStyle(bodyStyle) { fontSize = 26, fontStyle = FontStyle.Bold };
            smallStyle = new GUIStyle(bodyStyle) { fontSize = 15 };
            instructionStyle = new GUIStyle(bodyStyle) { fontSize = 18 };
            timerCaptionStyle = new GUIStyle(bodyStyle) { fontSize = 13, alignment = TextAnchor.MiddleRight };
            labelStyle = new GUIStyle(bodyStyle) { fontSize = 14, alignment = TextAnchor.MiddleCenter };
            ingredientNameStyle = new GUIStyle(bodyStyle) { fontSize = 16, fontStyle = FontStyle.Bold, wordWrap = false };
            statusStyle = new GUIStyle(bodyStyle) { fontSize = 14 };
            statusStyle.normal.textColor = new Color(0.65f, 0.76f, 0.73f);
            buttonStyle = new GUIStyle(GUI.skin.label) { fontSize = 18, fontStyle = FontStyle.Bold, wordWrap = true, alignment = TextAnchor.MiddleCenter };
            buttonStyle.normal.textColor = ink;
            buttonStyle.hover.textColor = Color.white;
            buttonStyle.active.textColor = new Color(0.6f, 1f, 0.75f);
            timerStyle = new GUIStyle(titleStyle) { fontSize = 32, alignment = TextAnchor.MiddleRight };
            countStyle = new GUIStyle(titleStyle) { fontSize = 23, alignment = TextAnchor.MiddleRight };
            noticeTitleStyle = new GUIStyle(titleStyle) { fontSize = 23 };
            noticeTitleStyle.normal.textColor = new Color(0.76f, 1f, 0.85f);
            feedbackTitleStyle = new GUIStyle(bodyStyle) { fontSize = 32, fontStyle = FontStyle.Bold };
            feedbackTitleStyle.normal.textColor = new Color(0.8f, 1f, 0.88f);
            feedbackDetailStyle = new GUIStyle(bodyStyle) { fontSize = 20 };
        }
        private static void Fill(Rect rect, Color color)
        {
            Color old = GUI.color; GUI.color = color; GUI.DrawTexture(rect, Texture2D.whiteTexture); GUI.color = old;
        }
        private bool ActionButton(Rect rect, string text, bool primary = false, bool selected = false)
        {
            Fill(rect, primary || selected ? new Color(0.16f, 0.39f, 0.29f) : new Color(0.10f, 0.17f, 0.18f));
            Fill(new Rect(rect.x, rect.yMax - 2f, rect.width, 2f), primary || selected ? new Color(0.5f, 0.9f, 0.65f) : new Color(0.24f, 0.34f, 0.33f));
            return GUI.Button(rect, text, buttonStyle);
        }
        private void DrawIngredientTile(int code)
        {
            int ingredient = code - 10;
            bool allowed = RequiredAmount(ingredient) >= 0f;
            bool done = allowed && (trial == 0 ? !NeedsIngredient(ingredient) : included[ingredient]);
            bool activePour = pouring && pourObject == targets[code];
            Rect rect = LabelRect(code);
            Fill(rect, activePour ? new Color(0.22f, 0.17f, 0.06f, 0.98f)
                : hovered == code ? new Color(0.15f, 0.29f, 0.25f, 0.98f) : done
                ? new Color(0.07f, 0.20f, 0.15f, 0.97f) : new Color(0.035f, 0.10f, 0.11f, 0.97f));
            Fill(new Rect(rect.x, rect.y, 3f, rect.height), ingredientMaterials[ingredient].color);
            GUI.Label(new Rect(rect.x + 10f, rect.y + 3f, rect.width - 18f, 23f), ingredientNames[ingredient], ingredientNameStyle);
            GUI.Label(new Rect(rect.x + 10f, rect.y + 26f, rect.width - 18f, 19f),
                activePour ? "Pouring..." : (done && trial == 0 ? "DONE  " : "") + IngredientProgress(ingredient), statusStyle);
        }
        private void DrawNotice()
        {
            if (Time.unscaledTime >= noticeUntil) return;
            if (noticeCelebrate) { DrawPositiveFeedback(); return; }
            float width = Mathf.Min(640f, Screen.width - 32f);
            Rect rect = new Rect((Screen.width - width) * 0.5f, Screen.height - 220f, width, 84f);
            Fill(rect, noticeSuccess ? new Color(0.035f, 0.18f, 0.13f, 0.98f) : new Color(0.22f, 0.17f, 0.08f, 0.98f));
            Fill(new Rect(rect.x, rect.y, 5f, rect.height), noticeSuccess ? new Color(0.5f, 0.95f, 0.65f) : new Color(1f, 0.77f, 0.35f));
            GUI.Label(new Rect(rect.x + 18f, rect.y + 5f, width - 36f, 32f), noticeTitle, noticeTitleStyle);
            GUI.Label(new Rect(rect.x + 18f, rect.y + 39f, width - 36f, 40f), noticeDetail, smallStyle);
        }
        private void DrawPositiveFeedback()
        {
            float age = Mathf.Max(0f, Time.unscaledTime - noticeStarted);
            float enter = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(age / 0.18f));
            float alpha = Mathf.Min(Mathf.Clamp01(age / 0.08f), Mathf.Clamp01((noticeUntil - Time.unscaledTime) / 0.25f));
            float width = Mathf.Min(760f, Screen.width - 32f);
            float textWidth = width - 108f;
            string heading = "GOOD JOB! " + noticeTitle;
            float titleHeight = Mathf.Max(36f, feedbackTitleStyle.CalcHeight(new GUIContent(heading), textWidth));
            float detailHeight = Mathf.Max(26f, feedbackDetailStyle.CalcHeight(new GUIContent(noticeDetail), textWidth));
            float height = Mathf.Max(108f, titleHeight + detailHeight + 36f);
            Rect panel = new Rect((Screen.width - width) * 0.5f,
                Screen.height - 136f - height + (1f - enter) * 12f, width, height);
            Matrix4x4 savedMatrix = GUI.matrix;
            Color savedColor = GUI.color;
            try
            {
                // UI만 작게 나타나게 합니다. 카메라/입력/타이머는 변경하지 않습니다.
                float scale = 0.96f + 0.04f * enter;
                GUIUtility.ScaleAroundPivot(new Vector2(scale, scale), panel.center);
                GUI.color = new Color(savedColor.r, savedColor.g, savedColor.b, savedColor.a * alpha);
                Fill(panel, new Color(0.025f, 0.19f, 0.12f, 0.98f * alpha));
                Fill(new Rect(panel.x, panel.y, 6f, panel.height), new Color(0.4f, 1f, 0.65f, alpha));
                Rect badge = new Rect(panel.x + 18f, panel.center.y - 27f, 54f, 54f);
                Fill(badge, new Color(0.14f, 0.62f, 0.35f, alpha));
                DrawFeedbackStroke(new Vector2(badge.x + 11f, badge.y + 28f), new Vector2(badge.x + 23f, badge.y + 40f), alpha);
                DrawFeedbackStroke(new Vector2(badge.x + 23f, badge.y + 40f), new Vector2(badge.x + 44f, badge.y + 15f), alpha);
                GUI.Label(new Rect(panel.x + 88f, panel.y + 12f, textWidth, titleHeight), heading, feedbackTitleStyle);
                GUI.Label(new Rect(panel.x + 88f, panel.y + 20f + titleHeight, textWidth, detailHeight), noticeDetail, feedbackDetailStyle);
            }
            finally { GUI.matrix = savedMatrix; GUI.color = savedColor; }
        }

        private static void DrawFeedbackStroke(Vector2 start, Vector2 end, float alpha)
        {
            Matrix4x4 saved = GUI.matrix;
            Vector2 delta = end - start;
            GUIUtility.RotateAroundPivot(Mathf.Atan2(delta.y, delta.x) * Mathf.Rad2Deg, start);
            Fill(new Rect(start.x, start.y - 2f, delta.magnitude, 4f), new Color(0.94f, 1f, 0.96f, alpha));
            GUI.matrix = saved;
        }

        private void Exit()
        {
            if (!IsActive) return;
            IsActive = false;
            if (owner.sounds != null) owner.sounds.StopAll();
            if (camera != null) camera.enabled = false;
            if (owner.playerCamera != null) owner.playerCamera.enabled = savedCamera;
            if (sourceMovement != null) sourceMovement.enabled = savedMovement;
            if (owner.uniform != null) owner.uniform.enabled = savedUniform;
            Cursor.lockState = savedCursor; Cursor.visible = savedCursorVisible;
            owner.practiceReturnFrame = Time.frameCount;
            ReleaseResources();
            if (serviceOrder && owner.night != null) owner.night.CompleteCocktail(completed && !failed);
        }
        private void ReleaseResources()
        {
            if (released) return;
            released = true;
            if (root != null) root.SetActive(false);
            if (scene.IsValid() && scene.isLoaded && Application.isPlaying) UnityEngine.SceneManagement.SceneManager.UnloadSceneAsync(scene);
            foreach (Material material in materials) if (material != null) UnityEngine.Object.Destroy(material);
            foreach (Mesh mesh in meshes) if (mesh != null) UnityEngine.Object.Destroy(mesh);
        }
        private Rect ServiceTicketRect() { return new Rect(16f, 16f, Mathf.Min(248f, Screen.width * 0.25f), 296f); }
        private void DrawService()
        {
            if (failed)
            {
                Fill(new Rect(0f, 0f, Screen.width, Screen.height), new Color(0f, 0f, 0f, 0.82f));
                float width = Mathf.Min(650f, Screen.width - 32f);
                Rect panel = new Rect((Screen.width - width) * 0.5f, (Screen.height - 340f) * 0.5f, width, 340f);
                Fill(panel, panelColor);
                GUI.Label(new Rect(panel.x + 26f, panel.y + 26f, width - 52f, 44f), "ORDER FAILED", titleStyle);
                GUI.Label(new Rect(panel.x + 26f, panel.y + 90f, width - 52f, 130f), error + "\n\nOne attempt per order. This customer will leave without a drink.", bodyStyle);
                if (ActionButton(new Rect(panel.x + 26f, panel.yMax - 82f, width - 52f, 54f), "RETURN TO BAR", true)) Exit();
                return;
            }
            owner.night.DrawTicket(ServiceTicketRect());
            float left = ServiceTicketRect().xMax + 16f;
            Fill(new Rect(left, 16f, Screen.width - left - 16f, 112f), panelColor);
            GUI.Label(new Rect(left + 14f, 24f, Screen.width - left - 210f, 36f), "CUSTOMER ORDER / ONE ATTEMPT", smallStyle);
            GUI.Label(new Rect(left + 14f, 62f, Screen.width - left - 210f, 56f), StageLabel(), bodyStyle);
            Color old = GUI.color; GUI.color = remaining <= 10f ? new Color(1f, 0.44f, 0.32f) : ink;
            GUI.Label(new Rect(Screen.width - 184f, 28f, 150f, 43f), remaining.ToString("0.0") + " s", timerStyle); GUI.color = old;
            GUI.Label(new Rect(Screen.width - 184f, 78f, 150f, 24f), "45 SECONDS", timerCaptionStyle);
            foreach (int code in targets.Keys)
            {
                if (!ShowTargetLabel(code)) continue;
                if (code >= 10 && code < 20) { DrawIngredientTile(code); continue; }
                Rect rect = LabelRect(code); Fill(rect, panelColor); GUI.Label(rect, TargetName(code), labelStyle);
            }
            DrawMeasureControls();
            Rect hint = new Rect(334f, Screen.height - 118f, Mathf.Max(150f, Screen.width - 566f), 102f);
            Fill(hint, panelColor);
            bool mixing = phase == Phase.Stir || phase == Phase.Shake;
            GUI.Label(new Rect(hint.x + 12f, hint.y + 7f, hint.width - 24f, 32f), mixing
                ? (phase == Phase.Stir ? "STIR" : "SHAKE") + "  " + (strokes / 2) + " / 15"
                : phase == Phase.Ready ? "READY TO SERVE" : "MAKE THE ORDERED DRINK", bodyStyle);
            GUI.Label(new Rect(hint.x + 12f, hint.y + 43f, hint.width - 24f, 50f), mixing
                ? "Hold LEFT CLICK and move " + (phase == Phase.Stir ? "left / right." : "up / down.")
                : "ENTER / SERVE submits. ESC cancels this order.", smallStyle);
            if (!pouring && ActionButton(FinishButton(), "SERVE", true)) TryFinish();
            DrawNotice();
        }

        private void DrawTrialIntro()
        {
            Fill(new Rect(0f, 0f, Screen.width, Screen.height), new Color(0f, 0f, 0f, 0.8f));
            float width = Mathf.Min(740f, Screen.width - 32f);
            Rect panel = new Rect((Screen.width - width) * 0.5f, (Screen.height - 470f) * 0.5f, width, 470f);
            Fill(panel, panelColor);
            GUI.Label(new Rect(panel.x + 28f, panel.y + 18f, width - 56f, 30f), recipeNames[recipe], smallStyle);
            GUI.Label(new Rect(panel.x + 28f, panel.y + 55f, width - 56f, 44f), "TRIAL " + (trial + 1) + " / 3 - " + trialNames[trial], titleStyle);
            owner.DrawTrialChecks(new Rect(panel.x + 28f, panel.y + 112f, width - 56f, 34f), recipe, smallStyle);
            GUI.Label(new Rect(panel.x + 28f, panel.y + 162f, width - 56f, 64f), trialDescriptions[trial], bodyStyle);
            GUI.Label(new Rect(panel.x + 28f, panel.y + 240f, width - 56f, 110f),
                "Click objects to use them. Flip the jigger with R or click its cups.\nHold LEFT CLICK to stir or shake. Press ENTER to submit.\nESC returns to the bar. Your " + RoundSeconds.ToString("0") + " seconds start after BEGIN.", smallStyle);
            float buttonWidth = (width - 72f) * 0.5f;
            if (ActionButton(new Rect(panel.x + 28f, panel.yMax - 76f, buttonWidth, 48f), "BEGIN TRIAL " + (trial + 1), true))
            {
                awaitingStart = false;
                Notify("TRIAL STARTED", RoundSeconds.ToString("0") + " seconds. Choose the " + glassNames[recipe] + ".");
            }
            if (ActionButton(new Rect(panel.center.x + 8f, panel.yMax - 76f, buttonWidth, 48f), "Back to the bar")) Exit();
        }
        private void DrawTrialResult()
        {
            Fill(new Rect(0f, 0f, Screen.width, Screen.height), new Color(0f, 0f, 0f, 0.8f));
            bool courseDone = completed && owner.AllTrialsComplete;
            float width = Mathf.Min(740f, Screen.width - 32f);
            float height = courseDone ? 500f : 430f;
            Rect panel = new Rect((Screen.width - width) * 0.5f, (Screen.height - height) * 0.5f, width, height);
            Fill(panel, panelColor);
            Fill(new Rect(panel.x, panel.y, width, 5f), completed ? new Color(0.5f, 0.9f, 0.65f) : new Color(1f, 0.56f, 0.3f));
            string heading = failed ? "TRY AGAIN" : courseDone ? "TRIAL COMPLETE" : "TRIAL " + (trial + 1) + " COMPLETE";
            GUI.Label(new Rect(panel.x + 28f, panel.y + 24f, width - 56f, 44f), heading, titleStyle);
            if (courseDone)
            {
                GUI.Label(new Rect(panel.x + 28f, panel.y + 82f, width - 56f, 48f), "All three cocktails, all three trials passed.\nOpen the bar?", bodyStyle);
                for (int recipeIndex = 0; recipeIndex < 3; recipeIndex++)
                {
                    float rowY = panel.y + 148f + recipeIndex * 72f;
                    GUI.Label(new Rect(panel.x + 28f, rowY, width - 56f, 28f), recipeNames[recipeIndex], smallStyle);
                    owner.DrawTrialChecks(new Rect(panel.x + 28f, rowY + 27f, width - 56f, 34f), recipeIndex, smallStyle);
                }
            }
            else
            {
                GUI.Label(new Rect(panel.x + 28f, panel.y + 84f, width - 56f, 104f), failed ? error
                    : recipeNames[recipe] + " / " + trialNames[trial] + " passed.\n"
                    + (owner.passedTrials[recipe] < 3 ? "Continue with less guidance in the next trial." : "All trials for this recipe are complete."), bodyStyle);
                owner.DrawTrialChecks(new Rect(panel.x + 28f, panel.y + 214f, width - 56f, 34f), recipe, smallStyle);
                GUI.Label(new Rect(panel.x + 28f, panel.y + 268f, width - 56f, 52f), failed
                    ? "This trial was not checked. Retry with a fresh " + RoundSeconds.ToString("0") + " seconds."
                    : owner.passedTrials[recipe] >= 3 ? "Return to the table and choose another recipe." : "The next trial starts with a short control reminder.", smallStyle);
            }
            float buttonWidth = (width - 72f) * 0.5f;
            Rect primary = new Rect(panel.x + 28f, panel.yMax - 76f, buttonWidth, 48f);
            Rect secondary = new Rect(panel.center.x + 8f, panel.yMax - 76f, buttonWidth, 48f);
            string action = failed ? "RETRY TRIAL " + (trial + 1) : courseDone ? "OPEN THE BAR"
                : owner.passedTrials[recipe] < 3 ? "NEXT TRIAL" : "BACK TO RECIPES";
            if (ActionButton(primary, action, true))
            {
                if (failed) ResetRound();
                else if (courseDone) owner.OpenBar();
                else if (owner.passedTrials[recipe] < 3) { trial = owner.passedTrials[recipe]; ResetRound(); }
                else Exit();
            }
            if (ActionButton(secondary, "Back to the bar")) Exit();
        }
        private void DrawMeasureControls()
        {
            Rect measures = MeasurePanel(); Fill(measures, panelColor);
            GUI.Label(new Rect(measures.x + 12f, measures.y + 7f, 278f, 25f), "JIGGER AMOUNT / R TO FLIP", smallStyle);
            bool previousEnabled = GUI.enabled; GUI.enabled = !pouring && !toolHeld;
            if (ActionButton(new Rect(measures.x + 12f, measures.y + 38f, 132f, 48f), "0.5 oz", false, measure == 0.5f)) SetMeasure(0.5f);
            if (ActionButton(new Rect(measures.x + 158f, measures.y + 38f, 132f, 48f), "1 oz", false, measure == 1f)) SetMeasure(1f);
            GUI.enabled = previousEnabled;
        }
        private void DrawRecallHUD()
        {
            Fill(new Rect(16f, 16f, Screen.width - 32f, 112f), panelColor);
            GUI.Label(new Rect(32f, 20f, Screen.width - 330f, 20f), "TRIAL 2 / 3 - INGREDIENT RECALL", smallStyle);
            GUI.Label(new Rect(32f, 42f, Screen.width - 340f, 34f), recipeNames[recipe], titleStyle);
            GUI.Label(new Rect(32f, 74f, Screen.width - 326f, 44f), "Glass: " + glassNames[recipe] + ". Use the listed ingredients.", instructionStyle);
            GUI.Label(new Rect(Screen.width - 270f, 29f, 150f, 43f), remaining.ToString("0.0") + " s", timerStyle);
            if (ActionButton(new Rect(Screen.width - 112f, 28f, 80f, 32f), "EXIT")) { Exit(); return; }
            foreach (int code in targets.Keys)
            {
                if (!ShowTargetLabel(code)) continue;
                if (code >= 10 && code < 20) { DrawIngredientTile(code); continue; }
                Rect rect = LabelRect(code); Fill(rect, panelColor); GUI.Label(rect, TargetName(code), labelStyle);
            }
            DrawMeasureControls();
            Rect hint = new Rect(334f, Screen.height - 118f, Screen.width - 566f, 102f);
            Fill(hint, panelColor);
            GUI.Label(new Rect(hint.x + 12f, hint.y + 8f, hint.width - 24f, 35f), "MAKE IT FROM MEMORY", smallStyle);
            GUI.Label(new Rect(hint.x + 12f, hint.y + 45f, hint.width - 24f, 46f), "Press ENTER or FINISH when you are ready.", smallStyle);
            if (!pouring && ActionButton(FinishButton(), "FINISH COCKTAIL", true)) TryFinish();
            DrawNotice();
        }
        public void Draw()
        {
            if (!IsActive) return;
            EnsureStyles();
            if (serviceOrder) { DrawService(); return; }
            if (awaitingStart) { DrawTrialIntro(); return; }
            if (failed || completed) { DrawTrialResult(); return; }
            if (trial == 2)
            {
                Rect timer = TimerOnlyRect();
                Fill(timer, panelColor);
                GUI.Label(timer, remaining.ToString("0.0") + " s", timerStyle);
                return;
            }
            if (trial == 1) { DrawRecallHUD(); return; }
            Fill(new Rect(16f, 16f, Screen.width - 32f, 112f), panelColor);
            GUI.Label(new Rect(32f, 20f, Screen.width - 330f, 20f), "TRIAL 1 / 3 - " + StageLabel(), smallStyle);
            GUI.Label(new Rect(32f, 42f, Screen.width - 340f, 34f), recipeNames[recipe], titleStyle);
            GUI.Label(new Rect(32f, 74f, Screen.width - 326f, 44f), pouring ? "Pouring into the vessel..." : NextInstruction(), instructionStyle);
            Color old = GUI.color; GUI.color = remaining <= 10f ? new Color(1f, 0.44f, 0.32f) : ink;
            GUI.Label(new Rect(Screen.width - 270f, 29f, 150f, 43f), remaining.ToString("0.0") + " s", timerStyle); GUI.color = old;
            GUI.Label(new Rect(Screen.width - 270f, 77f, 150f, 24f), "SECONDS LEFT / " + RoundSeconds.ToString("0"), timerCaptionStyle);
            Fill(new Rect(32f, 124f, (Screen.width - 64f) * remaining / RoundSeconds, 3f), remaining <= 10f ? new Color(1f, 0.44f, 0.32f) : new Color(0.4f, 0.8f, 0.6f));
            if (ActionButton(new Rect(Screen.width - 112f, 28f, 80f, 32f), "EXIT")) { Exit(); return; }
            foreach (int code in targets.Keys)
            {
                if (!ShowTargetLabel(code)) continue;
                if (code >= 10 && code < 20) { DrawIngredientTile(code); continue; }
                Rect rect = LabelRect(code);
                Fill(rect, hovered == code ? new Color(0.14f, 0.34f, 0.25f, 0.98f) : panelColor);
                GUI.Label(rect, TargetName(code), labelStyle);
            }
            DrawMeasureControls();
            Rect progress = new Rect(334f, Screen.height - 118f, Screen.width - 350f, 102f);
            Fill(progress, panelColor);
            if (phase == Phase.Stir || phase == Phase.Shake)
            {
                GUI.Label(new Rect(progress.x + 12f, progress.y + 7f, progress.width - 130f, 30f), phase == Phase.Stir ? "STIRRING" : "SHAKING", titleStyle);
                GUI.Label(new Rect(progress.xMax - 112f, progress.y + 7f, 100f, 30f), (strokes / 2) + " / 15", countStyle);
                string gesture = phase == Phase.Stir ? "left / right" : "up / down";
                GUI.Label(new Rect(progress.x + 12f, progress.y + 41f, progress.width - 24f, 32f), toolHeld
                    ? "Hold LEFT CLICK and move " + gesture + "." : "Click the highlighted tool to start.", smallStyle);
                Fill(new Rect(progress.x + 12f, progress.y + 83f, (progress.width - 24f) * Mathf.Clamp01(strokes / 30f), 7f), new Color(0.4f, 0.85f, 0.6f));
            }
            else if (phase == Phase.Ready)
            {
                GUI.Label(new Rect(progress.x + 12f, progress.y + 10f, progress.width - 220f, 32f), pouring ? "FINISHING POUR" : "READY TO SERVE", bodyStyle);
                GUI.Label(new Rect(progress.x + 12f, progress.y + 47f, progress.width - 220f, 40f), pouring ? "Wait for the pour to finish." : "All checks complete.", smallStyle);
                if (!pouring && ActionButton(FinishButton(), "FINISH COCKTAIL", true)) TryFinish();
            }
            else
            {
                int done = CompletedIngredientCount(); int total = recipeIngredients[recipe].Length;
                GUI.Label(new Rect(progress.x + 12f, progress.y + 7f, progress.width - 130f, 30f), "RECIPE PROGRESS", bodyStyle);
                GUI.Label(new Rect(progress.xMax - 112f, progress.y + 7f, 100f, 30f), done + " / " + total, countStyle);
                GUI.Label(new Rect(progress.x + 12f, progress.y + 41f, progress.width - 24f, 32f), phase == Phase.ChooseGlass
                    ? "Choose your glass to begin." : "Any ingredient order. Match the amounts above.", smallStyle);
                Fill(new Rect(progress.x + 12f, progress.y + 83f, (progress.width - 24f) * done / total, 7f), new Color(0.4f, 0.85f, 0.6f));
            }
            DrawNotice();
        }
        public void Dispose()
        {
            Exit();
            ReleaseResources();
        }
    }

    private sealed class RecipeCards
    {
        private readonly BeerGlassPour owner;
        private GameObject root;
        private readonly GameObject[] notes = new GameObject[3];
        private readonly Material[] paper = new Material[3];
        private readonly Material[] artMaterials = new Material[3];
        private readonly string[] titles = { "Gin & Tonic", "Negroni", "Long Island Iced Tea" };
        private readonly string[] shortTitles = { "Gin & Tonic", "Negroni", "Long Island" };
        private readonly string[] noteTitles = { "GIN & TONIC", "NEGRONI", "LONG ISLAND\nICED TEA" };
        private readonly string[] methods = { "BUILD IN GLASS", "STIR IN GLASS", "SHAKE & TOP" };
        private readonly string[] glasses = { "Rocks glass", "Old-fashioned glass", "Long-drink glass" };
        private readonly string[] descriptions = { "Gin, tonic and ice. Keep it simple.", "Equal parts. Stirred over ice.", "Four spirits. Shake, then top." };
        private readonly string[][] ingredientNames = {
            new[] { "Gin", "Tonic water", "Ice" },
            new[] { "Sweet vermouth", "Gin", "Campari", "Ice" },
            new[] { "Rum", "Gin", "Vodka", "Triple sec", "Lemon juice", "Cola", "Ice" }
        };
        private readonly string[][] amounts = {
            new[] { "1 oz", "Top up", "As needed" },
            new[] { "1 oz", "1 oz", "1 oz", "As needed" },
            new[] { "0.5 oz", "0.5 oz", "0.5 oz", "0.5 oz", "1 oz", "Top up", "As needed" }
        };
        private readonly string[][] steps = {
            new[] { "Choose a rocks glass.", "Measure 1 oz of gin accurately and pour it into the glass.", "Fill with tonic water.", "Add ice and serve." },
            new[] { "Choose an old-fashioned glass.", "Measure and pour 1 oz each of sweet vermouth, gin and Campari.", "Add ice and stir thoroughly." },
            new[] { "Prepare a long-drink glass.", "Measure 0.5 oz each of rum, gin, vodka and triple sec into the shaker.", "Add ice and shake thoroughly.", "Pour into the long-drink glass filled with ice.", "Add 1 oz of lemon juice on top.", "Top up with cola." }
        };
        private readonly Color ink = new Color(0.13f, 0.20f, 0.20f);
        private readonly Color muted = new Color(0.40f, 0.43f, 0.39f);
        private readonly Color cream = new Color(246f / 255f, 239f / 255f, 228f / 255f);
        private readonly Color[] accents = { new Color(0.27f, 0.43f, 0.34f), new Color(0.65f, 0.29f, 0.22f), new Color(0.65f, 0.45f, 0.16f) };
        private readonly System.Collections.Generic.List<Font> ownedFonts = new System.Collections.Generic.List<Font>();
        private Font font;
        private Font displayFont;
        private Texture2D illustration;
        private int selected = -1;
        private int hovered = -1;
        private int contentTab;
        private int closeFrame = -1;
        private Vector2 scroll;
        private CursorLockMode previousLock;
        private bool previousCursorVisible;
        private GUIStyle titleStyle, sectionStyle, bodyStyle, buttonStyle, smallStyle, amountStyle, numberStyle, centeredStyle;
        public bool IsOpen => selected >= 0;
        public bool BlocksInput => IsOpen || closeFrame == Time.frameCount;

        public RecipeCards(BeerGlassPour owner, BoxCollider table)
        {
            this.owner = owner;
            if (table == null) return;
            Font fallback = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            font = ChooseFont(new[] { "Helvetica Neue", "Arial", "Liberation Sans" }, fallback, 20);
            displayFont = ChooseFont(new[] { "Georgia", "Times New Roman", "Liberation Serif" }, font, 38);
            illustration = new Texture2D(2, 2, TextureFormat.RGB24, false);
            illustration.LoadImage(System.Convert.FromBase64String(RecipeIllustrationBase64), true);
            illustration.filterMode = FilterMode.Bilinear;
            illustration.wrapMode = TextureWrapMode.Clamp;
            Shader shader = Shader.Find("Universal Render Pipeline/Unlit");
            if (shader == null) shader = Shader.Find("Unlit/Color");
            if (shader == null) return;
            root = new GameObject("CocktailRecipeNotes_Runtime");
            UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root, owner.gameObject.scene);
            root.transform.position = table.transform.TransformPoint(table.center
                + Vector3.up * table.size.y * 0.5f) + Vector3.up * 0.004f;
            root.transform.rotation = table.transform.rotation;
            for (int index = 0; index < 3; index++)
            {
                GameObject note = GameObject.CreatePrimitive(PrimitiveType.Cube);
                note.name = "RecipeNote_" + (index + 1);
                note.transform.SetParent(root.transform, false);
                note.transform.localPosition = new Vector3(-1.9f + index * 0.43f, 0f, 0f);
                note.transform.localScale = new Vector3(0.30f, 0.003f, 0.36f);
                paper[index] = new Material(shader) { color = cream };
                note.GetComponent<Renderer>().sharedMaterial = paper[index];
                notes[index] = note;
                AddNoteText(index, noteTitles[index],
                    new Vector3(0f, 0.003f, 0.16f), 0.016f);
                GameObject art = GameObject.CreatePrimitive(PrimitiveType.Quad);
                art.name = "CocktailIllustration";
                art.transform.SetParent(root.transform, false);
                art.transform.localPosition = note.transform.localPosition + new Vector3(0f, 0.0035f, -0.015f);
                art.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
                art.transform.localScale = new Vector3(0.13f, 0.26f, 1f);
                Collider collider = art.GetComponent<Collider>();
                collider.enabled = false;
                UnityEngine.Object.Destroy(collider);
                artMaterials[index] = new Material(shader) { color = Color.white };
                artMaterials[index].mainTexture = illustration;
                artMaterials[index].mainTextureScale = new Vector2(1f / 3f, 1f);
                artMaterials[index].mainTextureOffset = new Vector2(index / 3f, 0f);
                art.GetComponent<Renderer>().sharedMaterial = artMaterials[index];
            }
            root.SetActive(false);
        }

        private Font ChooseFont(string[] choices, Font fallback, int size)
        {
            string[] installed = Font.GetOSInstalledFontNames();
            foreach (string name in choices)
            {
                if (!System.Array.Exists(installed, candidate => string.Equals(candidate, name, System.StringComparison.OrdinalIgnoreCase))) continue;
                Font chosen = Font.CreateDynamicFontFromOSFont(name, size);
                if (chosen == null) continue;
                ownedFonts.Add(chosen);
                return chosen;
            }
            return fallback;
        }

        private void AddNoteText(int index, string content, Vector3 offset, float size)
        {
            GameObject writing = new GameObject("PrintedRecipeLabel");
            writing.transform.SetParent(root.transform, false);
            writing.transform.localPosition = notes[index].transform.localPosition + offset;
            writing.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
            TextMesh text = writing.AddComponent<TextMesh>();
            text.font = font;
            text.fontSize = 48;
            text.characterSize = size;
            text.anchor = TextAnchor.UpperCenter;
            text.color = ink;
            font.RequestCharactersInTexture(content, text.fontSize);
            text.text = content;
            Renderer renderer = writing.GetComponent<Renderer>();
            renderer.sharedMaterial = font.material;
            Bounds bounds = renderer.localBounds;
            if (bounds.size.x > 0f && bounds.size.y > 0f)
                writing.transform.localScale = Vector3.one * Mathf.Min(0.26f / bounds.size.x, 0.04f / bounds.size.y);
        }

        public bool TryGetFocusPoint(out Vector3 point)
        {
            point = notes[1] != null ? notes[1].transform.position + Vector3.up * 0.02f : Vector3.zero;
            return notes[1] != null;
        }

        public void SetAvailable(bool available)
        {
            if (root != null && root.activeSelf != available) root.SetActive(available);
        }

        public bool HandleInput(bool clicked, out string prompt)
        {
            prompt = "";
            hovered = -1;
            if (root == null || !root.activeInHierarchy || BlocksInput
                || !owner.cocktailBriefingCompleted || owner.IsGuidePlaying) return false;
            Ray ray = owner.playerCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
            if (!Physics.Raycast(ray, out RaycastHit hit, owner.pickupDistance,
                Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore)) return false;
            for (int index = 0; index < notes.Length; index++)
            {
                if (hit.collider.gameObject != notes[index]) continue;
                hovered = index;
                prompt = "LEFT CLICK - Read " + titles[index];
                if (clicked)
                {
                    previousLock = Cursor.lockState;
                    previousCursorVisible = Cursor.visible;
                    selected = index;
                    contentTab = 0;
                    scroll = Vector2.zero;
                    Cursor.lockState = CursorLockMode.None;
                    Cursor.visible = true;
                }
                return true;
            }
            return false;
        }

        public void Close()
        {
            if (!IsOpen) return;
            selected = -1;
            closeFrame = Time.frameCount;
            Cursor.lockState = previousLock;
            Cursor.visible = previousCursorVisible;
        }

        private GUIStyle TextStyle(int size, Font face, Color color, FontStyle weight = FontStyle.Normal)
        {
            GUIStyle style = new GUIStyle(GUI.skin.label) { font = face, fontSize = size, fontStyle = weight,
                wordWrap = true, padding = new RectOffset(0, 0, 0, 0) };
            style.normal.textColor = color;
            return style;
        }

        private void EnsureStyles()
        {
            if (bodyStyle != null) return;
            bodyStyle = TextStyle(22, font, ink);
            titleStyle = TextStyle(38, displayFont, ink);
            sectionStyle = TextStyle(15, font, muted, FontStyle.Bold);
            smallStyle = TextStyle(16, font, muted);
            amountStyle = TextStyle(22, font, accents[0], FontStyle.Bold);
            amountStyle.alignment = TextAnchor.UpperRight;
            numberStyle = TextStyle(19, font, muted, FontStyle.Bold);
            centeredStyle = TextStyle(16, font, muted);
            centeredStyle.alignment = TextAnchor.MiddleCenter;
            buttonStyle = TextStyle(18, font, ink, FontStyle.Bold);
            buttonStyle.alignment = TextAnchor.MiddleCenter;
            buttonStyle.hover.textColor = new Color(0.25f, 0.5f, 0.36f);
            buttonStyle.active.textColor = buttonStyle.hover.textColor;
        }

        private static void Fill(Rect rect, Color color)
        {
            Color previous = GUI.color;
            GUI.color = color;
            GUI.DrawTexture(rect, Texture2D.whiteTexture);
            GUI.color = previous;
        }

        private bool Button(Rect rect, string label, bool active = false)
        {
            Fill(rect, active ? new Color(0.87f, 0.88f, 0.81f) : new Color(1f, 1f, 1f, 0.32f));
            return GUI.Button(rect, label, buttonStyle);
        }

        private void DrawIllustration(Rect space)
        {
            if (illustration == null) return;
            float aspect = illustration.width / (3f * illustration.height);
            float width = Mathf.Min(space.width, space.height * aspect);
            float height = width / aspect;
            Rect picture = new Rect(space.center.x - width * 0.5f, space.center.y - height * 0.5f, width, height);
            GUI.DrawTextureWithTexCoords(picture, illustration, new Rect(selected / 3f, 0f, 1f / 3f, 1f));
        }

        private void SwitchTo(int index)
        {
            selected = (index + 3) % 3;
            contentTab = 0;
            scroll = Vector2.zero;
            // Rebuild GUILayout before drawing a different number of recipe rows.
            GUIUtility.ExitGUI();
        }

        private void SwitchContent(int tab)
        {
            if (contentTab == tab) return;
            contentTab = tab;
            scroll = Vector2.zero;
            GUIUtility.ExitGUI();
        }

        public void DrawOverlay()
        {
            if (!IsOpen) return;
            EnsureStyles();
            Fill(new Rect(0, 0, Screen.width, Screen.height), new Color(0.025f, 0.055f, 0.055f, 0.86f));
            const float width = 1040f;
            const float height = 680f;
            float scale = Mathf.Min((Screen.width - 32f) / width, (Screen.height - 32f) / height, 1.15f);
            Matrix4x4 previousMatrix = GUI.matrix;
            GUI.matrix = Matrix4x4.TRS(new Vector3((Screen.width - width * scale) * 0.5f,
                (Screen.height - height * scale) * 0.5f, 0f), Quaternion.identity, new Vector3(scale, scale, 1f));
            try
            {
                Fill(new Rect(8f, 12f, width, height), new Color(0f, 0f, 0f, 0.2f));
                Fill(new Rect(0f, 0f, width, height), cream);
                Fill(new Rect(0f, 0f, width, 5f), accents[selected]);
                GUI.Label(new Rect(36f, 24f, 300f, 22f), "THE  BAR  BOOK", sectionStyle);
                GUI.Label(new Rect(36f, 55f, 290f, 28f), "RECIPE 0" + (selected + 1) + " / 03", smallStyle);
                if (Button(new Rect(844f, 20f, 160f, 36f), "CLOSE [ESC]")) { Close(); return; }
                for (int index = 0; index < 3; index++)
                    if (Button(new Rect(384f + index * 208f, 66f, 200f, 34f), shortTitles[index], selected == index))
                        SwitchTo(index);
                Fill(new Rect(352f, 112f, 1f, 487f), new Color(0.78f, 0.78f, 0.7f, 0.65f));
                DrawIllustration(new Rect(36f, 112f, 280f, 365f));
                Fill(new Rect(64f, 493f, 224f, 32f), new Color(accents[selected].r, accents[selected].g, accents[selected].b, 0.10f));
                GUI.Label(new Rect(64f, 493f, 224f, 32f), methods[selected], centeredStyle);
                GUI.Label(new Rect(36f, 535f, 280f, 28f), glasses[selected], centeredStyle);
                owner.DrawTrialChecks(new Rect(36f, 573f, 280f, 34f), selected, smallStyle);
                GUI.Label(new Rect(384f, 119f, 620f, 53f), titles[selected], titleStyle);
                GUI.Label(new Rect(384f, 180f, 620f, 28f), "Any ingredient order. Match quantities and technique.", smallStyle);

                if (Button(new Rect(384f, 219f, 300f, 36f), "INGREDIENTS", contentTab == 0)) SwitchContent(0);
                if (Button(new Rect(696f, 219f, 308f, 36f), "METHOD", contentTab == 1)) SwitchContent(1);
                GUILayout.BeginArea(new Rect(384f, 271f, 620f, 321f));
                scroll = GUILayout.BeginScrollView(scroll, false, false);
                if (contentTab == 0)
                {
                    for (int row = 0; row < ingredientNames[selected].Length; row++)
                    {
                        GUILayout.BeginHorizontal();
                        GUILayout.Label(ingredientNames[selected][row], bodyStyle, GUILayout.MinHeight(32f));
                        GUILayout.Label(amounts[selected][row], amountStyle, GUILayout.Width(135f));
                        GUILayout.EndHorizontal();
                        Fill(GUILayoutUtility.GetRect(1f, 1f, GUILayout.ExpandWidth(true)), new Color(0.78f, 0.78f, 0.7f, 0.5f));
                        GUILayout.Space(11f);
                    }
                }
                else
                {
                    for (int step = 0; step < steps[selected].Length; step++)
                    {
                        GUILayout.BeginHorizontal();
                        GUILayout.Label((step + 1).ToString("00"), numberStyle, GUILayout.Width(38f));
                        GUILayout.Label(steps[selected][step], bodyStyle, GUILayout.MinHeight(32f));
                        GUILayout.EndHorizontal();
                        GUILayout.Space(16f);
                    }
                }
                GUILayout.EndScrollView();
                GUILayout.EndArea();

                Fill(new Rect(36f, 614f, 968f, 1f), new Color(0.78f, 0.78f, 0.7f));
                string startLabel = owner.AllTrialsComplete && !owner.barOpened ? "Open the bar?"
                    : owner.passedTrials[selected] >= 3 ? "Practice again" : owner.passedTrials[selected] == 0
                    ? "Start to make" : "Start trial " + (owner.passedTrials[selected] + 1);
                if (Button(new Rect(36f, 622f, 280f, 42f), startLabel, true))
                {
                    if (owner.AllTrialsComplete && !owner.barOpened) owner.OpenBar();
                    else owner.BeginPractice(selected);
                    GUIUtility.ExitGUI();
                }
                if (Button(new Rect(384f, 622f, 155f, 42f), "<  PREVIOUS")) SwitchTo(selected - 1);
                GUI.Label(new Rect(630f, 622f, 130f, 42f), "0" + (selected + 1) + " / 03", centeredStyle);
                if (Button(new Rect(849f, 622f, 155f, 42f), "NEXT  >")) SwitchTo(selected + 1);
            }
            finally { GUI.matrix = previousMatrix; }
        }

        public void Dispose()
        {
            Close();
            if (root != null) UnityEngine.Object.Destroy(root);
            foreach (Material material in paper) if (material != null) UnityEngine.Object.Destroy(material);
            foreach (Material material in artMaterials) if (material != null) UnityEngine.Object.Destroy(material);
            foreach (Font owned in ownedFonts) if (owned != null) UnityEngine.Object.Destroy(owned);
            if (illustration != null) UnityEngine.Object.Destroy(illustration);
        }

        // Embedded artwork keeps the illustrated cards in the existing five-script Mac sync.
        private const string RecipeIllustrationBase64 = "";
    }

}

// 조작/충돌 판정과 분리된 런타임 안내 표시입니다. 새 씬/프리팹/Inspector 연결은 필요하지 않습니다.
internal sealed class WaypointBeacon
{
    private readonly GameObject root;
    private readonly Transform core, halo, labelTransform;
    private readonly Transform[] sparks = new Transform[6];
    private readonly Transform[] dots;
    private readonly Material green, pale;
    private readonly Mesh star;
    private readonly TextMesh label;
    private string caption = "";
    private bool disposed;

    public WaypointBeacon(GameObject owner, bool createCore, bool createTrail)
    {
        Shader shader = Shader.Find("Universal Render Pipeline/Unlit");
        if (shader == null) shader = Shader.Find("Unlit/Color");
        if (shader == null) return;
        green = new Material(shader) { color = new Color(0.2f, 1f, 0.5f) };
        pale = new Material(shader) { color = new Color(0.8f, 1f, 0.9f) };
        if (pale.HasProperty("_Cull")) pale.SetInt("_Cull", 0);
        root = new GameObject(createCore ? "StationWaypoint_Runtime" : "ClockWaypoint_Runtime");
        root.layer = 2; // Ignore Raycast; 아래 모든 장식에도 Collider를 두지 않습니다.
        UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root, owner.scene);
        if (createCore) core = Sphere("GuideOrb", root.transform, green).transform;
        halo = Child("OrbitRing");
        LineRenderer ring = halo.gameObject.AddComponent<LineRenderer>();
        ring.sharedMaterial = green; ring.useWorldSpace = false; ring.loop = true;
        ring.positionCount = 48; ring.widthMultiplier = 0.014f;
        for (int index = 0; index < 48; index++)
        {
            float angle = index * Mathf.PI * 2f / 48f;
            ring.SetPosition(index, new Vector3(Mathf.Cos(angle) * 0.22f, 0f, Mathf.Sin(angle) * 0.22f));
        }
        star = CreateStar();
        for (int index = 0; index < sparks.Length; index++)
        {
            sparks[index] = Child("GuideSparkle");
            sparks[index].gameObject.AddComponent<MeshFilter>().sharedMesh = star;
            sparks[index].gameObject.AddComponent<MeshRenderer>().sharedMaterial = pale;
        }
        dots = new Transform[createTrail ? 18 : 0];
        for (int index = 0; index < dots.Length; index++)
        {
            dots[index] = Sphere("GuideTrailDot", root.transform, green).transform;
            dots[index].gameObject.SetActive(false);
        }
        labelTransform = Child("WaypointCaption");
        label = labelTransform.gameObject.AddComponent<TextMesh>();
        label.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
        label.fontSize = 64; label.characterSize = 0.045f; label.fontStyle = FontStyle.Bold;
        label.anchor = TextAnchor.MiddleCenter; label.alignment = TextAlignment.Center;
        label.color = new Color(0.86f, 1f, 0.9f);
        label.GetComponent<Renderer>().sharedMaterial = label.font.material;
        root.SetActive(false);
    }

    private Transform Child(string name)
    {
        GameObject child = new GameObject(name); child.layer = 2;
        child.transform.SetParent(root.transform, false);
        return child.transform;
    }

    private static GameObject Sphere(string name, Transform parent, Material material)
    {
        GameObject sphere = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        sphere.name = name; sphere.layer = 2;
        sphere.transform.SetParent(parent, false);
        Collider collider = sphere.GetComponent<Collider>();
        collider.enabled = false; UnityEngine.Object.Destroy(collider);
        sphere.GetComponent<Renderer>().sharedMaterial = material;
        return sphere;
    }

    private static Mesh CreateStar()
    {
        Vector3[] vertices = new Vector3[9];
        int[] triangles = new int[24];
        for (int index = 0; index < 8; index++)
        {
            float angle = index * Mathf.PI * 0.25f;
            float radius = index % 2 == 0 ? 1f : 0.23f;
            vertices[index + 1] = new Vector3(Mathf.Cos(angle) * radius, Mathf.Sin(angle) * radius, 0f);
            triangles[index * 3] = 0;
            triangles[index * 3 + 1] = index + 1;
            triangles[index * 3 + 2] = (index + 1) % 8 + 1;
        }
        Mesh mesh = new Mesh { name = "GuideSparkle_Runtime", vertices = vertices, triangles = triangles };
        mesh.RecalculateNormals(); mesh.RecalculateBounds();
        return mesh;
    }

    public void Show(Vector3 anchor, Camera viewer, string title)
    {
        if (disposed || root == null || viewer == null) return;
        root.SetActive(true);
        float time = Time.unscaledTime;
        float pulse = 0.5f + 0.5f * Mathf.Sin(time * 2.4f);
        root.transform.position = anchor + (core != null ? Vector3.up * Mathf.Sin(time * 1.8f) * 0.08f : Vector3.zero);
        if (core != null) core.localScale = Vector3.one * Mathf.Lerp(0.18f, 0.23f, pulse);
        green.color = Color.Lerp(new Color(0.08f, 0.55f, 0.25f), new Color(0.3f, 1f, 0.6f), pulse);
        halo.localRotation = Quaternion.Euler(18f, time * 36f, 12f);
        halo.localScale = Vector3.one * Mathf.Lerp(0.9f, 1.1f, pulse);
        for (int index = 0; index < sparks.Length; index++)
        {
            float angle = time * 1.1f + index * Mathf.PI * 2f / sparks.Length;
            sparks[index].localPosition = new Vector3(Mathf.Cos(angle) * 0.24f,
                Mathf.Sin(time * 1.7f + index) * 0.11f, Mathf.Sin(angle) * 0.24f);
            sparks[index].localScale = Vector3.one * Mathf.Lerp(0.012f, 0.036f,
                0.5f + 0.5f * Mathf.Sin(time * 3.2f + index * 1.3f));
            sparks[index].rotation = viewer.transform.rotation;
        }
        labelTransform.localPosition = Vector3.up * 0.36f;
        Vector3 away = labelTransform.position - viewer.transform.position;
        if (away.sqrMagnitude > 0.0001f) labelTransform.rotation = Quaternion.LookRotation(away, Vector3.up);
        if (caption != title || labelTransform.localScale == Vector3.one)
        {
            caption = title;
            label.font.RequestCharactersInTexture(title, label.fontSize, label.fontStyle);
            label.text = title;
            labelTransform.localScale = Vector3.one;
            Bounds bounds = label.GetComponent<Renderer>().localBounds;
            if (bounds.size.x > 0f && bounds.size.y > 0f)
                labelTransform.localScale = Vector3.one * Mathf.Min(1.7f / bounds.size.x, 0.14f / bounds.size.y);
        }
    }

    public void SetTrail(Vector3 start, Vector3 end, float floorY)
    {
        if (root == null || disposed || dots == null || dots.Length == 0) return;
        start.y = end.y = floorY + 0.07f;
        float length = Vector3.Distance(start, end);
        int count = length < 0.65f ? 0 : Mathf.Clamp(Mathf.CeilToInt(length / 0.6f), 2, dots.Length);
        for (int index = 0; index < dots.Length; index++)
        {
            dots[index].gameObject.SetActive(index < count);
            if (index >= count) continue;
            float along = Mathf.Repeat(index * length / count + Time.unscaledTime * 0.55f, length);
            dots[index].position = Vector3.Lerp(start, end, along / length);
            dots[index].localScale = Vector3.one * (0.04f + 0.014f * Mathf.Sin(Time.unscaledTime * 2.4f + index));
        }
    }

    public void Hide() { if (root != null) root.SetActive(false); }

    public void Dispose()
    {
        if (disposed) return;
        disposed = true;
        if (root != null) UnityEngine.Object.Destroy(root);
        if (green != null) UnityEngine.Object.Destroy(green);
        if (pale != null) UnityEngine.Object.Destroy(pale);
        if (star != null) UnityEngine.Object.Destroy(star);
    }
}

// 착용/집기/따르기/서빙/도구/카드의 조준 입력 안내에만 사용하는 공통 표시입니다.
// 기존 동기화 파일 안에 두어 새 Inspector 연결이나 에셋이 필요하지 않습니다.
internal static class InteractionPromptUI
{
    private static GUIStyle style;

    public static void Draw(string message)
    {
        if (string.IsNullOrEmpty(message) || Cursor.lockState != CursorLockMode.Locked) return;
        if (style == null)
        {
            style = new GUIStyle(GUI.skin.label) { fontStyle = FontStyle.Bold,
                alignment = TextAnchor.MiddleCenter, wordWrap = true,
                padding = new RectOffset(0, 0, 0, 0) };
            style.normal.textColor = Color.white;
        }
        style.fontSize = Mathf.Clamp(Mathf.RoundToInt(Screen.height * (32f / 600f)), 28, 44);
        GUIContent content = new GUIContent(message);
        float maxWidth = Mathf.Min(1000f, Screen.width - 48f);
        float width = Mathf.Min(maxWidth, Mathf.Max(320f, style.CalcSize(content).x + 32f));
        float height = Mathf.Max(style.fontSize + 16f, style.CalcHeight(content, width - 32f) + 16f);
        float y = Mathf.Min(Screen.height * 0.5f + 16f, Screen.height - height - 20f);
        Rect panel = new Rect((Screen.width - width) * 0.5f, Mathf.Max(16f, y), width, height);
        Color old = GUI.color;
        GUI.color = new Color(0.02f, 0.055f, 0.065f, 0.94f);
        GUI.DrawTexture(panel, Texture2D.whiteTexture);
        GUI.color = old;
        GUI.Label(new Rect(panel.x + 16f, panel.y + 8f, width - 32f, height - 16f), message, style);
    }
}
